def _e(x):
    return _html.escape(str(x if x is not None else ""), quote=True)


def _ok(x):
    return isinstance(x, (int, float)) and not (isinstance(x, float) and math.isnan(x))


def _prep(df):
    """\u0e40\u0e23\u0e35\u0e22\u0e07\u0e04\u0e2d\u0e25\u0e31\u0e21\u0e19\u0e4c\u0e08\u0e32\u0e01\u0e44\u0e15\u0e23\u0e21\u0e32\u0e2a\u0e25\u0e48\u0e32\u0e2a\u0e38\u0e14 \u2192 \u0e40\u0e01\u0e48\u0e32\u0e2a\u0e38\u0e14 \u00b7 \u0e16\u0e49\u0e32\u0e44\u0e21\u0e48\u0e21\u0e35\u0e02\u0e49\u0e2d\u0e21\u0e39\u0e25\u0e04\u0e37\u0e19 None"""
    if df is None or getattr(df, "empty", True):
        return None
    try:
        return df.sort_index(axis=1, ascending=False)
    except Exception:
        return df


def _get(df, labels, i):
    if df is None or i is None or i >= df.shape[1]:
        return None
    for lb in labels:
        if lb in df.index:
            try:
                v = df.loc[lb].iloc[i]
            except Exception:
                continue
            if _ok(v):
                return float(v)
    return None


def _yoy_idx(df):
    """\u0e15\u0e33\u0e41\u0e2b\u0e19\u0e48\u0e07\u0e04\u0e2d\u0e25\u0e31\u0e21\u0e19\u0e4c\u0e02\u0e2d\u0e07\u0e44\u0e15\u0e23\u0e21\u0e32\u0e2a\u0e40\u0e14\u0e35\u0e22\u0e27\u0e01\u0e31\u0e19\u0e40\u0e21\u0e37\u0e48\u0e2d\u0e1b\u0e35\u0e01\u0e48\u0e2d\u0e19 (\u0e2b\u0e48\u0e32\u0e07\u0e23\u0e32\u0e27 1 \u0e1b\u0e35) \u00b7 \u0e44\u0e21\u0e48\u0e21\u0e35 = None"""
    if df is None or df.shape[1] < 5:
        return None
    try:
        gap = (pd.Timestamp(df.columns[0]) - pd.Timestamp(df.columns[4])).days
        return 4 if 300 <= gap <= 430 else None
    except Exception:
        return None


def _money(x):
    if not _ok(x):
        return "\u2014"
    a = abs(x)
    if a >= 1e9:
        return "%s%.1f \u0e1e\u0e31\u0e19\u0e25\u0e49\u0e32\u0e19\u0e14\u0e2d\u0e25\u0e25\u0e32\u0e23\u0e4c" % ("-" if x < 0 else "", a / 1e9)
    if a >= 1e6:
        return "%s%s \u0e25\u0e49\u0e32\u0e19\u0e14\u0e2d\u0e25\u0e25\u0e32\u0e23\u0e4c" % ("-" if x < 0 else "", format(a / 1e6, ",.0f"))
    return "%s%s \u0e14\u0e2d\u0e25\u0e25\u0e32\u0e23\u0e4c" % ("-" if x < 0 else "", format(a, ",.0f"))


def _pct(x, d=1, sign=False):
    return "\u2014" if not _ok(x) else (("%+." + str(d) + "f%%") if sign else ("%." + str(d) + "f%%")) % x


def _pts(x, d=1):
    return "\u2014" if not _ok(x) else ("%+." + str(d) + "f \u0e08\u0e38\u0e14") % x


def _lens(key, title, stance, head, rows=None, note="", watch="", data=None):
    return {"key": key, "title": title, "stance": stance, "head": head, "rows": rows or [], "note": note, "watch": watch, "d": data or {}}


def _na(key, title, why):
    return _lens(key, title, "na", why)


