# \u0e42\u0e2b\u0e25\u0e14\u0e02\u0e49\u0e2d\u0e21\u0e39\u0e25 (\u0e41\u0e04\u0e0a 1 \u0e0a\u0e31\u0e48\u0e27\u0e42\u0e21\u0e07) \u2014 \u0e2a\u0e48\u0e27\u0e19\u0e44\u0e2b\u0e19\u0e1e\u0e25\u0e32\u0e14\u0e01\u0e47\u0e02\u0e49\u0e32\u0e21 \u0e44\u0e21\u0e48\u0e25\u0e49\u0e21\u0e17\u0e31\u0e49\u0e07\u0e2b\u0e19\u0e49\u0e32
# ---------------------------------------------------------------
@st.cache_data(ttl=3600, show_spinner=False)
def _load(sym):
    t = yf.Ticker(sym)
    out = {}

    def grab(name, fn):
        try:
            out[name] = fn()
        except Exception:
            out[name] = None

    grab("inc", lambda: t.quarterly_income_stmt)
    grab("cf", lambda: t.quarterly_cashflow)
    grab("bs", lambda: t.quarterly_balance_sheet)
    grab("ed", lambda: t.get_earnings_dates(limit=12))
    grab("rev_est", lambda: t.revenue_estimate)
    grab("eps_est", lambda: t.earnings_estimate)
    grab("info", lambda: t.info)
    try:
        out["tnx"] = float(yf.Ticker("^TNX").history(period="5d")["Close"].dropna().iloc[-1])
    except Exception:
        out["tnx"] = None
    return out


