def _adj_eps_by_quarter(inc, ed, n=6):
    """\u0e08\u0e31\u0e1a\u0e04\u0e39\u0e48 Reported EPS (\u0e15\u0e31\u0e27\u0e40\u0e25\u0e02\u0e17\u0e35\u0e48\u0e23\u0e32\u0e22\u0e07\u0e32\u0e19) \u0e01\u0e31\u0e1a\u0e41\u0e15\u0e48\u0e25\u0e30\u0e44\u0e15\u0e23\u0e21\u0e32\u0e2a\u0e43\u0e19\u0e07\u0e1a: \u0e27\u0e31\u0e19\u0e1b\u0e23\u0e30\u0e01\u0e32\u0e28\u0e2d\u0e22\u0e39\u0e48\u0e2b\u0e25\u0e31\u0e07\u0e2a\u0e34\u0e49\u0e19\u0e44\u0e15\u0e23\u0e21\u0e32\u0e2a\u0e44\u0e21\u0e48\u0e40\u0e01\u0e34\u0e19 ~85 \u0e27\u0e31\u0e19"""
    res = {}
    if ed is None or getattr(ed, "empty", True) or "Reported EPS" not in ed.columns:
        return res
    e = ed.copy()
    idx = pd.to_datetime(e.index)
    try:
        idx = idx.tz_localize(None)
    except Exception:
        pass
    e.index = idx
    e = e[e["Reported EPS"].notna()].sort_index()
    for i, qd in enumerate(list(inc.columns)[:n]):
        qd = pd.Timestamp(qd)
        cand = e[(e.index > qd) & (e.index <= qd + pd.Timedelta(days=85))]
        if len(cand):
            res[i] = float(cand.iloc[0]["Reported EPS"])
    return res


def lens_quality(D):
    key, title = "quality", "\u0e04\u0e38\u0e13\u0e20\u0e32\u0e1e\u0e01\u0e33\u0e44\u0e23 \u2014 \u0e1a\u0e31\u0e0d\u0e0a\u0e35 vs \u0e15\u0e31\u0e27\u0e40\u0e25\u0e02\u0e17\u0e35\u0e48\u0e1b\u0e23\u0e31\u0e1a\u0e1b\u0e23\u0e38\u0e07\u0e41\u0e25\u0e49\u0e27"
    inc = _prep(D.get("inc"))
    if inc is None:
        return _na(key, title, "\u0e44\u0e21\u0e48\u0e21\u0e35\u0e07\u0e1a\u0e23\u0e32\u0e22\u0e44\u0e15\u0e23\u0e21\u0e32\u0e2a\u0e43\u0e2b\u0e49\u0e40\u0e17\u0e35\u0e22\u0e1a")
    y = _yoy_idx(inc)
    g0 = _get(inc, ["Diluted EPS", "Basic EPS"], 0)
    gy = _get(inc, ["Diluted EPS", "Basic EPS"], y) if y else None
    adj = _adj_eps_by_quarter(inc, D.get("ed"))
    a0, ay = adj.get(0), adj.get(y) if y else None
    rows = []
    if g0 is not None:
        rows.append(("\u0e01\u0e33\u0e44\u0e23\u0e15\u0e48\u0e2d\u0e2b\u0e38\u0e49\u0e19\u0e15\u0e32\u0e21\u0e1a\u0e31\u0e0d\u0e0a\u0e35 (\u0e44\u0e15\u0e23\u0e21\u0e32\u0e2a\u0e25\u0e48\u0e32\u0e2a\u0e38\u0e14)", "%.2f \u0e14\u0e2d\u0e25\u0e25\u0e32\u0e23\u0e4c" % g0))
    if a0 is not None:
        rows.append(("\u0e01\u0e33\u0e44\u0e23\u0e15\u0e48\u0e2d\u0e2b\u0e38\u0e49\u0e19\u0e17\u0e35\u0e48\u0e1b\u0e23\u0e31\u0e1a\u0e1b\u0e23\u0e38\u0e07\u0e41\u0e25\u0e49\u0e27 (Reported EPS)", "%.2f \u0e14\u0e2d\u0e25\u0e25\u0e32\u0e23\u0e4c" % a0))
    if g0 is None or a0 is None or a0 <= 0 or g0 <= 0:
        return _lens(key, title, "na", "\u0e40\u0e17\u0e35\u0e22\u0e1a\u0e2a\u0e2d\u0e07\u0e15\u0e31\u0e27\u0e40\u0e25\u0e02\u0e19\u0e35\u0e49\u0e44\u0e21\u0e48\u0e44\u0e14\u0e49 (\u0e02\u0e49\u0e2d\u0e21\u0e39\u0e25\u0e44\u0e21\u0e48\u0e04\u0e23\u0e1a \u0e2b\u0e23\u0e37\u0e2d\u0e01\u0e33\u0e44\u0e23\u0e15\u0e34\u0e14\u0e25\u0e1a)", rows,
                     note="Yahoo \u0e44\u0e21\u0e48\u0e21\u0e35\u0e15\u0e31\u0e27\u0e40\u0e25\u0e02\u0e1b\u0e23\u0e31\u0e1a\u0e1b\u0e23\u0e38\u0e07\u0e2d\u0e22\u0e48\u0e32\u0e07\u0e40\u0e1b\u0e47\u0e19\u0e17\u0e32\u0e07\u0e01\u0e32\u0e23\u0e2a\u0e33\u0e2b\u0e23\u0e31\u0e1a\u0e17\u0e38\u0e01\u0e2b\u0e38\u0e49\u0e19 \u0e25\u0e2d\u0e07\u0e40\u0e0a\u0e47\u0e01\u0e41\u0e16\u0e25\u0e07\u0e07\u0e1a\u0e02\u0e2d\u0e07\u0e1a\u0e23\u0e34\u0e29\u0e31\u0e17\u0e42\u0e14\u0e22\u0e15\u0e23\u0e07")
    r0 = g0 / a0 * 100
    rows.append(("\u0e01\u0e33\u0e44\u0e23\u0e15\u0e32\u0e21\u0e1a\u0e31\u0e0d\u0e0a\u0e35 \u00f7 \u0e17\u0e35\u0e48\u0e1b\u0e23\u0e31\u0e1a\u0e1b\u0e23\u0e38\u0e07\u0e41\u0e25\u0e49\u0e27", _pct(r0)))
    stance, head, watch = "mid", "\u0e0a\u0e48\u0e2d\u0e07\u0e27\u0e48\u0e32\u0e07\u0e23\u0e30\u0e2b\u0e27\u0e48\u0e32\u0e07\u0e2a\u0e2d\u0e07\u0e15\u0e31\u0e27\u0e40\u0e25\u0e02\u0e43\u0e01\u0e25\u0e49\u0e40\u0e04\u0e35\u0e22\u0e07\u0e1b\u0e35\u0e01\u0e48\u0e2d\u0e19", ""
    ry, distorted = None, False
    if gy is not None and ay is not None and gy > 0 and ay > 0:
        ry = gy / ay * 100
        d = r0 - ry
        gg, ga = (g0 / gy - 1) * 100, (a0 / ay - 1) * 100
        rows += [("\u0e2a\u0e31\u0e14\u0e2a\u0e48\u0e27\u0e19\u0e40\u0e14\u0e35\u0e22\u0e27\u0e01\u0e31\u0e19\u0e40\u0e21\u0e37\u0e48\u0e2d\u0e1b\u0e35\u0e01\u0e48\u0e2d\u0e19", _pct(ry)), ("\u0e01\u0e33\u0e44\u0e23\u0e15\u0e32\u0e21\u0e1a\u0e31\u0e0d\u0e0a\u0e35\u0e42\u0e15 (\u0e40\u0e17\u0e35\u0e22\u0e1a\u0e1b\u0e35\u0e01\u0e48\u0e2d\u0e19)", _pct(gg, 0, True)),
                 ("\u0e17\u0e35\u0e48\u0e1b\u0e23\u0e31\u0e1a\u0e1b\u0e23\u0e38\u0e07\u0e41\u0e25\u0e49\u0e27\u0e42\u0e15 (\u0e40\u0e17\u0e35\u0e22\u0e1a\u0e1b\u0e35\u0e01\u0e48\u0e2d\u0e19)", _pct(ga, 0, True))]
        distorted = ry < 60 and (r0 - ry) >= 25          # \u0e1b\u0e35\u0e01\u0e48\u0e2d\u0e19\u0e01\u0e33\u0e44\u0e23\u0e15\u0e32\u0e21\u0e1a\u0e31\u0e0d\u0e0a\u0e35\u0e15\u0e48\u0e33\u0e01\u0e27\u0e48\u0e32\u0e17\u0e35\u0e48\u0e1b\u0e23\u0e31\u0e1a\u0e1b\u0e23\u0e38\u0e07\u0e21\u0e32\u0e01 = \u0e19\u0e48\u0e32\u0e08\u0e30\u0e21\u0e35\u0e23\u0e32\u0e22\u0e01\u0e32\u0e23\u0e1e\u0e34\u0e40\u0e28\u0e29\u0e02\u0e19\u0e32\u0e14\u0e43\u0e2b\u0e0d\u0e48 \u0e10\u0e32\u0e19\u0e40\u0e17\u0e35\u0e22\u0e1a\u0e40\u0e1e\u0e35\u0e49\u0e22\u0e19
        if d >= 3:
            stance, head = "good", "\u0e0a\u0e48\u0e2d\u0e07\u0e27\u0e48\u0e32\u0e07\u0e41\u0e04\u0e1a\u0e25\u0e07 \u2014 \u0e23\u0e32\u0e22\u0e01\u0e32\u0e23\u0e17\u0e35\u0e48\u0e16\u0e39\u0e01\u0e1b\u0e23\u0e31\u0e1a\u0e2d\u0e2d\u0e01\u0e40\u0e25\u0e47\u0e01\u0e25\u0e07\u0e40\u0e21\u0e37\u0e48\u0e2d\u0e40\u0e17\u0e35\u0e22\u0e1a\u0e01\u0e31\u0e1a\u0e02\u0e19\u0e32\u0e14\u0e18\u0e38\u0e23\u0e01\u0e34\u0e08 (\u0e2a\u0e31\u0e0d\u0e0d\u0e32\u0e13\u0e04\u0e38\u0e13\u0e20\u0e32\u0e1e)"
            if distorted:
                stance, head = "mid", "\u0e0a\u0e48\u0e2d\u0e07\u0e27\u0e48\u0e32\u0e07\u0e41\u0e04\u0e1a\u0e25\u0e07 \u0e41\u0e15\u0e48\u0e2a\u0e48\u0e27\u0e19\u0e43\u0e2b\u0e0d\u0e48\u0e40\u0e1e\u0e23\u0e32\u0e30\u0e1b\u0e35\u0e01\u0e48\u0e2d\u0e19\u0e21\u0e35\u0e23\u0e32\u0e22\u0e01\u0e32\u0e23\u0e1e\u0e34\u0e40\u0e28\u0e29\u0e02\u0e19\u0e32\u0e14\u0e43\u0e2b\u0e0d\u0e48 (\u0e01\u0e33\u0e44\u0e23\u0e15\u0e32\u0e21\u0e1a\u0e31\u0e0d\u0e0a\u0e35\u0e15\u0e48\u0e33\u0e01\u0e27\u0e48\u0e32\u0e17\u0e35\u0e48\u0e1b\u0e23\u0e31\u0e1a\u0e1b\u0e23\u0e38\u0e07\u0e21\u0e32\u0e01) \u0e10\u0e32\u0e19\u0e40\u0e17\u0e35\u0e22\u0e1a\u0e08\u0e36\u0e07\u0e40\u0e1e\u0e35\u0e49\u0e22\u0e19"
                watch = "\u0e14\u0e39\u0e41\u0e19\u0e27\u0e42\u0e19\u0e49\u0e21\u0e0a\u0e48\u0e2d\u0e07\u0e27\u0e48\u0e32\u0e07\u0e2b\u0e25\u0e32\u0e22\u0e44\u0e15\u0e23\u0e21\u0e32\u0e2a\u0e15\u0e48\u0e2d\u0e40\u0e19\u0e37\u0e48\u0e2d\u0e07 \u0e44\u0e21\u0e48\u0e43\u0e0a\u0e48\u0e40\u0e17\u0e35\u0e22\u0e1a\u0e01\u0e31\u0e1a\u0e44\u0e15\u0e23\u0e21\u0e32\u0e2a\u0e1b\u0e35\u0e01\u0e48\u0e2d\u0e19\u0e17\u0e35\u0e48\u0e21\u0e35\u0e23\u0e32\u0e22\u0e01\u0e32\u0e23\u0e1e\u0e34\u0e40\u0e28\u0e29"
        elif d <= -3:
            stance, head = "bad", "\u0e0a\u0e48\u0e2d\u0e07\u0e27\u0e48\u0e32\u0e07\u0e01\u0e27\u0e49\u0e32\u0e07\u0e02\u0e36\u0e49\u0e19 \u2014 \u0e01\u0e33\u0e44\u0e23\u0e17\u0e35\u0e48\u0e1b\u0e23\u0e31\u0e1a\u0e1b\u0e23\u0e38\u0e07\u0e41\u0e25\u0e49\u0e27\u0e14\u0e39\u0e14\u0e35\u0e01\u0e27\u0e48\u0e32\u0e01\u0e33\u0e44\u0e23\u0e08\u0e23\u0e34\u0e07\u0e21\u0e32\u0e01\u0e02\u0e36\u0e49\u0e19"
            watch = "\u0e14\u0e39\u0e27\u0e48\u0e32\u0e23\u0e32\u0e22\u0e01\u0e32\u0e23\u0e17\u0e35\u0e48\u0e16\u0e39\u0e01\u0e1b\u0e23\u0e31\u0e1a\u0e2d\u0e2d\u0e01\u0e04\u0e37\u0e2d\u0e2d\u0e30\u0e44\u0e23 (\u0e04\u0e48\u0e32\u0e15\u0e2d\u0e1a\u0e41\u0e17\u0e19\u0e40\u0e1b\u0e47\u0e19\u0e2b\u0e38\u0e49\u0e19 \u0e04\u0e48\u0e32\u0e15\u0e31\u0e14\u0e08\u0e33\u0e2b\u0e19\u0e48\u0e32\u0e22\u0e08\u0e32\u0e01\u0e01\u0e32\u0e23\u0e0b\u0e37\u0e49\u0e2d\u0e01\u0e34\u0e08\u0e01\u0e32\u0e23 \u0e04\u0e48\u0e32\u0e1b\u0e23\u0e31\u0e1a\u0e42\u0e04\u0e23\u0e07\u0e2a\u0e23\u0e49\u0e32\u0e07) \u0e41\u0e25\u0e30\u0e0b\u0e49\u0e33\u0e17\u0e38\u0e01\u0e44\u0e15\u0e23\u0e21\u0e32\u0e2a\u0e44\u0e2b\u0e21"
    else:
        head = "\u0e2a\u0e31\u0e14\u0e2a\u0e48\u0e27\u0e19\u0e1a\u0e31\u0e0d\u0e0a\u0e35 \u00f7 \u0e1b\u0e23\u0e31\u0e1a\u0e1b\u0e23\u0e38\u0e07 = %.0f%% (\u0e22\u0e31\u0e07\u0e44\u0e21\u0e48\u0e21\u0e35\u0e02\u0e49\u0e2d\u0e21\u0e39\u0e25\u0e1b\u0e35\u0e01\u0e48\u0e2d\u0e19\u0e21\u0e32\u0e40\u0e17\u0e35\u0e22\u0e1a\u0e41\u0e19\u0e27\u0e42\u0e19\u0e49\u0e21)" % r0
    return _lens(key, title, stance, head, rows,
                 note="\u0e15\u0e31\u0e27\u0e40\u0e25\u0e02 \"\u0e1b\u0e23\u0e31\u0e1a\u0e1b\u0e23\u0e38\u0e07\u0e41\u0e25\u0e49\u0e27\" \u0e43\u0e0a\u0e49 Reported EPS \u0e08\u0e32\u0e01 Yahoo \u0e0b\u0e36\u0e48\u0e07\u0e21\u0e31\u0e01\u0e40\u0e1b\u0e47\u0e19\u0e15\u0e31\u0e27\u0e40\u0e25\u0e02\u0e17\u0e35\u0e48\u0e1a\u0e23\u0e34\u0e29\u0e31\u0e17\u0e1b\u0e23\u0e31\u0e1a\u0e1b\u0e23\u0e38\u0e07 \u00b7 \u0e04\u0e27\u0e23\u0e40\u0e0a\u0e47\u0e01\u0e23\u0e32\u0e22\u0e01\u0e32\u0e23\u0e17\u0e35\u0e48\u0e1b\u0e23\u0e31\u0e1a\u0e43\u0e19\u0e41\u0e16\u0e25\u0e07\u0e07\u0e1a\u0e1b\u0e23\u0e30\u0e01\u0e2d\u0e1a", watch=watch, data={"ratio_now": r0, "ratio_prev": ry, "distorted": distorted})


