def lens_margin(D):
    key, title = "margin", "\u0e21\u0e32\u0e23\u0e4c\u0e08\u0e34\u0e49\u0e19\u0e21\u0e32\u0e08\u0e32\u0e01\u0e44\u0e2b\u0e19 \u2014 \u0e23\u0e32\u0e04\u0e32/\u0e15\u0e49\u0e19\u0e17\u0e38\u0e19 \u0e2b\u0e23\u0e37\u0e2d\u0e04\u0e38\u0e21\u0e04\u0e48\u0e32\u0e43\u0e0a\u0e49\u0e08\u0e48\u0e32\u0e22"
    inc = _prep(D.get("inc"))
    if inc is None:
        return _na(key, title, "\u0e44\u0e21\u0e48\u0e21\u0e35\u0e07\u0e1a\u0e23\u0e32\u0e22\u0e44\u0e15\u0e23\u0e21\u0e32\u0e2a")
    y = _yoy_idx(inc)
    base = y if y else (1 if inc.shape[1] >= 2 else None)
    if base is None:
        return _na(key, title, "\u0e02\u0e49\u0e2d\u0e21\u0e39\u0e25\u0e22\u0e49\u0e2d\u0e19\u0e2b\u0e25\u0e31\u0e07\u0e44\u0e21\u0e48\u0e1e\u0e2d")
    lab = "\u0e40\u0e17\u0e35\u0e22\u0e1a\u0e1b\u0e35\u0e01\u0e48\u0e2d\u0e19" if y else "\u0e40\u0e17\u0e35\u0e22\u0e1a\u0e44\u0e15\u0e23\u0e21\u0e32\u0e2a\u0e01\u0e48\u0e2d\u0e19"
    R = lambda i: _get(inc, ["Total Revenue", "Operating Revenue"], i)
    GP = lambda i: _get(inc, ["Gross Profit"], i)
    OI = lambda i: _get(inc, ["Operating Income", "EBIT"], i)
    r0, rb, o0, ob, g0, gb = R(0), R(base), OI(0), OI(base), GP(0), GP(base)
    if None in (r0, rb, o0, ob) or r0 <= 0 or rb <= 0:
        return _na(key, title, "\u0e44\u0e21\u0e48\u0e21\u0e35\u0e23\u0e32\u0e22\u0e44\u0e14\u0e49/\u0e01\u0e33\u0e44\u0e23\u0e08\u0e32\u0e01\u0e01\u0e32\u0e23\u0e14\u0e33\u0e40\u0e19\u0e34\u0e19\u0e07\u0e32\u0e19\u0e04\u0e23\u0e1a\u0e1e\u0e2d\u0e04\u0e33\u0e19\u0e27\u0e13")
