    key, title = "cash", "\u0e04\u0e38\u0e13\u0e20\u0e32\u0e1e\u0e40\u0e07\u0e34\u0e19\u0e2a\u0e14 \u2014 \u0e01\u0e33\u0e44\u0e23\u0e01\u0e25\u0e32\u0e22\u0e40\u0e1b\u0e47\u0e19\u0e40\u0e07\u0e34\u0e19\u0e2a\u0e14\u0e08\u0e23\u0e34\u0e07\u0e44\u0e2b\u0e21"
    inc, cf = _prep(D.get("inc")), _prep(D.get("cf"))
    if inc is None or cf is None:
        return _na(key, title, "\u0e44\u0e21\u0e48\u0e21\u0e35\u0e07\u0e1a\u0e01\u0e23\u0e30\u0e41\u0e2a\u0e40\u0e07\u0e34\u0e19\u0e2a\u0e14\u0e23\u0e32\u0e22\u0e44\u0e15\u0e23\u0e21\u0e32\u0e2a")
    n = min(4, inc.shape[1], cf.shape[1])
    ni = [_get(inc, ["Net Income", "Net Income Common Stockholders"], i) for i in range(n)]
    fcf = [_get(cf, ["Free Cash Flow"], i) for i in range(n)]
    if n < 4 or any(v is None for v in ni) or any(v is None for v in fcf):
        return _na(key, title, "\u0e02\u0e49\u0e2d\u0e21\u0e39\u0e25 4 \u0e44\u0e15\u0e23\u0e21\u0e32\u0e2a\u0e25\u0e48\u0e32\u0e2a\u0e38\u0e14\u0e44\u0e21\u0e48\u0e04\u0e23\u0e1a")
    ni_t, fcf_t = sum(ni), sum(fcf)
    rows = [("\u0e01\u0e33\u0e44\u0e23\u0e2a\u0e38\u0e17\u0e18\u0e34 4 \u0e44\u0e15\u0e23\u0e21\u0e32\u0e2a\u0e25\u0e48\u0e32\u0e2a\u0e38\u0e14", _money(ni_t)), ("\u0e40\u0e07\u0e34\u0e19\u0e2a\u0e14\u0e2d\u0e34\u0e2a\u0e23\u0e30 4 \u0e44\u0e15\u0e23\u0e21\u0e32\u0e2a\u0e25\u0e48\u0e32\u0e2a\u0e38\u0e14", _money(fcf_t))]
    conv = fcf_t / ni_t * 100 if ni_t > 0 else None
    if conv is not None:
        rows.append(("\u0e40\u0e07\u0e34\u0e19\u0e2a\u0e14\u0e2d\u0e34\u0e2a\u0e23\u0e30 \u00f7 \u0e01\u0e33\u0e44\u0e23\u0e2a\u0e38\u0e17\u0e18\u0e34", _pct(conv, 0)))
    y = _yoy_idx(inc)
    sb0 = _get(cf, ["Stock Based Compensation"], 0)
    r0 = _get(inc, ["Total Revenue", "Operating Revenue"], 0)
    sbp0 = sb0 / r0 * 100 if _ok(sb0) and _ok(r0) and r0 > 0 else None
    sbpy = None
    if y and _yoy_idx(cf):
        sby, ry = _get(cf, ["Stock Based Compensation"], y), _get(inc, ["Total Revenue", "Operating Revenue"], y)
        sbpy = sby / ry * 100 if _ok(sby) and _ok(ry) and ry > 0 else None
    if sbp0 is not None:
        rows.append(("\u0e04\u0e48\u0e32\u0e15\u0e2d\u0e1a\u0e41\u0e17\u0e19\u0e40\u0e1b\u0e47\u0e19\u0e2b\u0e38\u0e49\u0e19 \u00f7 \u0e23\u0e32\u0e22\u0e44\u0e14\u0e49", "%s%s" % (_pct(sbp0), (" (\u0e1b\u0e35\u0e01\u0e48\u0e2d\u0e19 %s)" % _pct(sbpy)) if sbpy is not None else "")))
    stance, head, watch = "mid", "\u0e41\u0e1b\u0e25\u0e07\u0e01\u0e33\u0e44\u0e23\u0e40\u0e1b\u0e47\u0e19\u0e40\u0e07\u0e34\u0e19\u0e2a\u0e14\u0e44\u0e14\u0e49\u0e1a\u0e32\u0e07\u0e2a\u0e48\u0e27\u0e19", ""
    if fcf_t <= 0:
        stance, head, watch = "bad", "\u0e40\u0e07\u0e34\u0e19\u0e2a\u0e14\u0e2d\u0e34\u0e2a\u0e23\u0e30 4 \u0e44\u0e15\u0e23\u0e21\u0e32\u0e2a\u0e25\u0e48\u0e32\u0e2a\u0e38\u0e14\u0e15\u0e34\u0e14\u0e25\u0e1a \u2014 \u0e18\u0e38\u0e23\u0e01\u0e34\u0e08\u0e22\u0e31\u0e07\u0e40\u0e1c\u0e32\u0e40\u0e07\u0e34\u0e19\u0e2a\u0e14", "\u0e14\u0e39\u0e27\u0e48\u0e32\u0e40\u0e1b\u0e47\u0e19\u0e01\u0e32\u0e23\u0e25\u0e07\u0e17\u0e38\u0e19\u0e02\u0e22\u0e32\u0e22\u0e01\u0e33\u0e25\u0e31\u0e07\u0e1c\u0e25\u0e34\u0e15 (\u0e0a\u0e31\u0e48\u0e27\u0e04\u0e23\u0e32\u0e27) \u0e2b\u0e23\u0e37\u0e2d\u0e18\u0e38\u0e23\u0e01\u0e34\u0e08\u0e2b\u0e25\u0e31\u0e01\u0e44\u0e21\u0e48\u0e2a\u0e23\u0e49\u0e32\u0e07\u0e40\u0e07\u0e34\u0e19\u0e2a\u0e14"
    elif conv is not None and conv >= 90:
        stance, head = "good", "\u0e01\u0e33\u0e44\u0e23\u0e41\u0e1b\u0e25\u0e07\u0e40\u0e1b\u0e47\u0e19\u0e40\u0e07\u0e34\u0e19\u0e2a\u0e14\u0e44\u0e14\u0e49\u0e14\u0e35 (\u226590%)"
    elif conv is not None and conv < 50:
        stance, head, watch = "bad", "\u0e01\u0e33\u0e44\u0e23\u0e41\u0e1b\u0e25\u0e07\u0e40\u0e1b\u0e47\u0e19\u0e40\u0e07\u0e34\u0e19\u0e2a\u0e14\u0e44\u0e14\u0e49\u0e19\u0e49\u0e2d\u0e22 (<50%) \u2014 \u0e15\u0e23\u0e27\u0e08\u0e14\u0e39\u0e25\u0e39\u0e01\u0e2b\u0e19\u0e35\u0e49 \u0e2a\u0e15\u0e47\u0e2d\u0e01 \u0e41\u0e25\u0e30\u0e01\u0e32\u0e23\u0e25\u0e07\u0e17\u0e38\u0e19", "\u0e40\u0e17\u0e35\u0e22\u0e1a\u0e01\u0e31\u0e1a\u0e2a\u0e15\u0e47\u0e2d\u0e01/\u0e25\u0e39\u0e01\u0e2b\u0e19\u0e35\u0e49\u0e43\u0e19\u0e40\u0e25\u0e19\u0e2a\u0e4c\u0e04\u0e27\u0e32\u0e21\u0e40\u0e2a\u0e35\u0e48\u0e22\u0e07\u0e25\u0e49\u0e19\u0e15\u0e25\u0e32\u0e14"
    if sbp0 is not None and sbpy is not None and sbp0 < sbpy - 0.5 and stance == "mid":
        head = head + " \u00b7 \u0e04\u0e48\u0e32\u0e15\u0e2d\u0e1a\u0e41\u0e17\u0e19\u0e40\u0e1b\u0e47\u0e19\u0e2b\u0e38\u0e49\u0e19\u0e40\u0e25\u0e47\u0e01\u0e25\u0e07\u0e40\u0e17\u0e35\u0e22\u0e1a\u0e23\u0e32\u0e22\u0e44\u0e14\u0e49"
    return _lens(key, title, stance, head, rows, note="\u0e01\u0e33\u0e44\u0e23\u0e17\u0e35\u0e48\u0e44\u0e21\u0e48\u0e40\u0e2b\u0e47\u0e19\u0e43\u0e19\u0e40\u0e07\u0e34\u0e19\u0e2a\u0e14\u0e15\u0e49\u0e2d\u0e07\u0e16\u0e32\u0e21\u0e27\u0e48\u0e32\u0e44\u0e1b\u0e2d\u0e22\u0e39\u0e48\u0e17\u0e35\u0e48\u0e44\u0e2b\u0e19 (\u0e2a\u0e15\u0e47\u0e2d\u0e01 \u0e25\u0e39\u0e01\u0e2b\u0e19\u0e35\u0e49 \u0e2b\u0e23\u0e37\u0e2d\u0e01\u0e32\u0e23\u0e25\u0e07\u0e17\u0e38\u0e19)", watch=watch, data={"conv": conv, "fcf": fcf_t, "ni": ni_t, "sbp0": sbp0, "sbpy": sbpy})


