def lens_cycle(D):
    key, title = "cycle", "\u0e04\u0e27\u0e32\u0e21\u0e40\u0e2a\u0e35\u0e48\u0e22\u0e07\u0e25\u0e49\u0e19\u0e15\u0e25\u0e32\u0e14 \u2014 \u0e2a\u0e15\u0e47\u0e2d\u0e01\u0e41\u0e25\u0e30\u0e25\u0e39\u0e01\u0e2b\u0e19\u0e35\u0e49 vs \u0e22\u0e2d\u0e14\u0e02\u0e32\u0e22"
    inc, bs = _prep(D.get("inc")), _prep(D.get("bs"))
    if inc is None or bs is None:
        return _na(key, title, "\u0e44\u0e21\u0e48\u0e21\u0e35\u0e07\u0e1a\u0e14\u0e38\u0e25\u0e23\u0e32\u0e22\u0e44\u0e15\u0e23\u0e21\u0e32\u0e2a")
    yi, yb = _yoy_idx(inc), _yoy_idx(bs)
    if not yi or not yb:
        return _na(key, title, "\u0e02\u0e49\u0e2d\u0e21\u0e39\u0e25\u0e22\u0e49\u0e2d\u0e19\u0e2b\u0e25\u0e31\u0e07\u0e44\u0e21\u0e48\u0e16\u0e36\u0e07\u0e1b\u0e35\u0e40\u0e15\u0e47\u0e21\u0e2a\u0e33\u0e2b\u0e23\u0e31\u0e1a\u0e40\u0e17\u0e35\u0e22\u0e1a")
    r0, ry = _get(inc, ["Total Revenue", "Operating Revenue"], 0), _get(inc, ["Total Revenue", "Operating Revenue"], yi)
    if not (_ok(r0) and _ok(ry) and ry > 0):
        return _na(key, title, "\u0e44\u0e21\u0e48\u0e21\u0e35\u0e23\u0e32\u0e22\u0e44\u0e14\u0e49\u0e40\u0e17\u0e35\u0e22\u0e1a\u0e1b\u0e35\u0e01\u0e48\u0e2d\u0e19")
    rg = (r0 / ry - 1) * 100
    rows = [("\u0e23\u0e32\u0e22\u0e44\u0e14\u0e49\u0e42\u0e15 (\u0e40\u0e17\u0e35\u0e22\u0e1a\u0e1b\u0e35\u0e01\u0e48\u0e2d\u0e19)", _pct(rg, 0, True))]
    iv0, ivy = _get(bs, ["Inventory"], 0), _get(bs, ["Inventory"], yb)
    ar0, ary = _get(bs, ["Accounts Receivable", "Receivables"], 0), _get(bs, ["Accounts Receivable", "Receivables"], yb)
    flags, gaps = [], []
    if _ok(iv0) and _ok(ivy) and ivy > 0:
        ig = (iv0 / ivy - 1) * 100
        rows.append(("\u0e2a\u0e15\u0e47\u0e2d\u0e01\u0e42\u0e15 (\u0e40\u0e17\u0e35\u0e22\u0e1a\u0e1b\u0e35\u0e01\u0e48\u0e2d\u0e19)", _pct(ig, 0, True)))
        gaps.append(ig - rg)
    if _ok(ar0) and _ok(ary) and ary > 0:
        ag = (ar0 / ary - 1) * 100
        rows.append(("\u0e25\u0e39\u0e01\u0e2b\u0e19\u0e35\u0e49\u0e01\u0e32\u0e23\u0e04\u0e49\u0e32\u0e42\u0e15 (\u0e40\u0e17\u0e35\u0e22\u0e1a\u0e1b\u0e35\u0e01\u0e48\u0e2d\u0e19)", _pct(ag, 0, True)))
        gaps.append(ag - rg)
        d0, dy = ar0 / r0 * 90, ary / ry * 90
        rows.append(("\u0e23\u0e30\u0e22\u0e30\u0e40\u0e01\u0e47\u0e1a\u0e2b\u0e19\u0e35\u0e49\u0e40\u0e09\u0e25\u0e35\u0e48\u0e22 (\u0e27\u0e31\u0e19)", "%.0f \u2192 %.0f" % (dy, d0)))
    if not gaps:
        return _lens(key, title, "na", "\u0e18\u0e38\u0e23\u0e01\u0e34\u0e08\u0e19\u0e35\u0e49\u0e44\u0e21\u0e48\u0e21\u0e35\u0e2a\u0e15\u0e47\u0e2d\u0e01/\u0e25\u0e39\u0e01\u0e2b\u0e19\u0e35\u0e49\u0e43\u0e2b\u0e49\u0e40\u0e17\u0e35\u0e22\u0e1a (\u0e40\u0e0a\u0e48\u0e19 \u0e0b\u0e2d\u0e1f\u0e15\u0e4c\u0e41\u0e27\u0e23\u0e4c/\u0e1a\u0e23\u0e34\u0e01\u0e32\u0e23) \u0e2b\u0e23\u0e37\u0e2d Yahoo \u0e44\u0e21\u0e48\u0e43\u0e2b\u0e49\u0e02\u0e49\u0e2d\u0e21\u0e39\u0e25", rows)
    worst = max(gaps)
    stance, head, watch = "mid", "\u0e2a\u0e15\u0e47\u0e2d\u0e01/\u0e25\u0e39\u0e01\u0e2b\u0e19\u0e35\u0e49\u0e42\u0e15\u0e43\u0e01\u0e25\u0e49\u0e40\u0e04\u0e35\u0e22\u0e07\u0e22\u0e2d\u0e14\u0e02\u0e32\u0e22", ""
    if worst >= 15:
        stance, head = "bad", "\u0e2a\u0e15\u0e47\u0e2d\u0e01\u0e2b\u0e23\u0e37\u0e2d\u0e25\u0e39\u0e01\u0e2b\u0e19\u0e35\u0e49\u0e42\u0e15\u0e40\u0e23\u0e47\u0e27\u0e01\u0e27\u0e48\u0e32\u0e22\u0e2d\u0e14\u0e02\u0e32\u0e22\u0e40\u0e01\u0e34\u0e19 15 \u0e08\u0e38\u0e14 \u2014 \u0e2a\u0e31\u0e0d\u0e0d\u0e32\u0e13\u0e41\u0e23\u0e01\u0e17\u0e35\u0e48\u0e21\u0e31\u0e01\u0e40\u0e2b\u0e47\u0e19\u0e01\u0e48\u0e2d\u0e19\u0e22\u0e2d\u0e14\u0e02\u0e32\u0e22\u0e0a\u0e30\u0e25\u0e2d"
        watch = "\u0e14\u0e39\u0e27\u0e48\u0e32\u0e2a\u0e15\u0e47\u0e2d\u0e01\u0e17\u0e35\u0e48\u0e40\u0e1e\u0e34\u0e48\u0e21\u0e04\u0e37\u0e2d\u0e27\u0e31\u0e15\u0e16\u0e38\u0e14\u0e34\u0e1a\u0e40\u0e15\u0e23\u0e35\u0e22\u0e21\u0e23\u0e31\u0e1a\u0e2d\u0e2d\u0e40\u0e14\u0e2d\u0e23\u0e4c \u0e2b\u0e23\u0e37\u0e2d\u0e2a\u0e34\u0e19\u0e04\u0e49\u0e32\u0e2a\u0e33\u0e40\u0e23\u0e47\u0e08\u0e23\u0e39\u0e1b\u0e17\u0e35\u0e48\u0e02\u0e32\u0e22\u0e44\u0e21\u0e48\u0e2d\u0e2d\u0e01"
    elif worst <= 0:
        stance, head = "good", "\u0e2a\u0e15\u0e47\u0e2d\u0e01\u0e41\u0e25\u0e30\u0e25\u0e39\u0e01\u0e2b\u0e19\u0e35\u0e49\u0e42\u0e15\u0e0a\u0e49\u0e32\u0e01\u0e27\u0e48\u0e32\u0e22\u0e2d\u0e14\u0e02\u0e32\u0e22 \u2014 \u0e44\u0e21\u0e48\u0e40\u0e2b\u0e47\u0e19\u0e2a\u0e31\u0e0d\u0e0d\u0e32\u0e13\u0e2a\u0e34\u0e19\u0e04\u0e49\u0e32\u0e25\u0e49\u0e19"
    return _lens(key, title, stance, head, rows, note="Over-invest (\u0e25\u0e39\u0e01\u0e04\u0e49\u0e32\u0e25\u0e07\u0e17\u0e38\u0e19\u0e40\u0e01\u0e34\u0e19) \u0e22\u0e31\u0e07\u0e44\u0e21\u0e48\u0e40\u0e17\u0e48\u0e32\u0e01\u0e31\u0e1a Oversupply (\u0e1c\u0e39\u0e49\u0e02\u0e32\u0e22\u0e1c\u0e25\u0e34\u0e15\u0e25\u0e49\u0e19) \u2014 \u0e40\u0e25\u0e19\u0e2a\u0e4c\u0e19\u0e35\u0e49\u0e40\u0e0a\u0e47\u0e01\u0e1d\u0e31\u0e48\u0e07\u0e1c\u0e39\u0e49\u0e02\u0e32\u0e22\u0e27\u0e48\u0e32\u0e40\u0e23\u0e34\u0e48\u0e21\u0e25\u0e49\u0e19\u0e08\u0e23\u0e34\u0e07\u0e2b\u0e23\u0e37\u0e2d\u0e22\u0e31\u0e07", watch=watch, data={"worst_gap": worst, "rev_g": rg})


