# \u0e40\u0e25\u0e19\u0e2a\u0e4c\u0e17\u0e35\u0e48 6 \u2014 \u0e23\u0e32\u0e04\u0e32\u0e04\u0e34\u0e14\u0e2d\u0e30\u0e44\u0e23\u0e2d\u0e22\u0e39\u0e48 (\u0e1a\u0e31\u0e19\u0e44\u0e14\u0e1b\u0e35)
