def years_to_base(pe, base, g):
    """\u0e15\u0e49\u0e2d\u0e07\u0e42\u0e15\u0e1b\u0e35\u0e25\u0e30 g (0.4 = 40%) \u0e01\u0e35\u0e48\u0e1b\u0e35 \u0e16\u0e36\u0e07\u0e08\u0e30\u0e17\u0e33\u0e43\u0e2b\u0e49 P/E \u0e25\u0e07\u0e21\u0e32\u0e40\u0e17\u0e48\u0e32\u0e40\u0e2a\u0e49\u0e19\u0e2d\u0e49\u0e32\u0e07\u0e2d\u0e34\u0e07 (\u0e2a\u0e21\u0e21\u0e15\u0e34\u0e23\u0e32\u0e04\u0e32\u0e04\u0e07\u0e17\u0e35\u0e48)"""
    if not (_ok(pe) and _ok(base) and pe > 0 and base > 0 and g > 0):
        return None
    if pe <= base:
        return 0.0
    return math.log(pe / base) / math.log(1 + g)


def lens_valuation(D):
    key, title = "valuation", "\u0e23\u0e32\u0e04\u0e32\u0e04\u0e34\u0e14\u0e2d\u0e30\u0e44\u0e23\u0e2d\u0e22\u0e39\u0e48 \u2014 P/E \u0e40\u0e17\u0e35\u0e22\u0e1a\u0e40\u0e2a\u0e49\u0e19\u0e2d\u0e49\u0e32\u0e07\u0e2d\u0e34\u0e07"
    info, tnx = D.get("info") or {}, D.get("tnx")
    pe = info.get("forwardPE")
    if not _ok(pe) or pe <= 0:
        pe = None
        px, feps = info.get("currentPrice", info.get("regularMarketPrice")), info.get("forwardEps")
        if _ok(px) and _ok(feps) and feps > 0:
            pe = px / feps
    if pe is None or not _ok(tnx) or tnx <= 0:
        return _na(key, title, "\u0e44\u0e21\u0e48\u0e21\u0e35 P/E \u0e25\u0e48\u0e27\u0e07\u0e2b\u0e19\u0e49\u0e32 \u0e2b\u0e23\u0e37\u0e2d\u0e44\u0e21\u0e48\u0e21\u0e35\u0e2d\u0e31\u0e15\u0e23\u0e32\u0e1c\u0e25\u0e15\u0e2d\u0e1a\u0e41\u0e17\u0e19\u0e1e\u0e31\u0e19\u0e18\u0e1a\u0e31\u0e15\u0e23 10 \u0e1b\u0e35")
    base = 100.0 / tnx
    ratio = pe / base
    rows = [("\u0e1e\u0e31\u0e19\u0e18\u0e1a\u0e31\u0e15\u0e23 10 \u0e1b\u0e35", _pct(tnx, 2)), ("\u0e40\u0e2a\u0e49\u0e19\u0e2d\u0e49\u0e32\u0e07\u0e2d\u0e34\u0e07 P/E (100 \u00f7 \u0e1c\u0e25\u0e15\u0e2d\u0e1a\u0e41\u0e17\u0e19)", "%.1f \u0e40\u0e17\u0e48\u0e32" % base),
            ("P/E \u0e25\u0e48\u0e27\u0e07\u0e2b\u0e19\u0e49\u0e32\u0e02\u0e2d\u0e07\u0e2b\u0e38\u0e49\u0e19", "%.1f \u0e40\u0e17\u0e48\u0e32" % pe), ("\u0e40\u0e17\u0e35\u0e22\u0e1a\u0e40\u0e2a\u0e49\u0e19\u0e2d\u0e49\u0e32\u0e07\u0e2d\u0e34\u0e07", "%.1f \u0e40\u0e17\u0e48\u0e32" % ratio)]
    ladder = {}
    for g in (0.2, 0.4, 0.6, 0.8):
        yrs = years_to_base(pe, base, g)
        ladder[int(g * 100)] = yrs
        rows.append(("\u0e16\u0e49\u0e32\u0e01\u0e33\u0e44\u0e23\u0e42\u0e15\u0e1b\u0e35\u0e25\u0e30 %d%% \u0e43\u0e0a\u0e49\u0e40\u0e27\u0e25\u0e32" % int(g * 100), "\u0e16\u0e36\u0e07\u0e40\u0e2a\u0e49\u0e19\u0e41\u0e25\u0e49\u0e27" if yrs == 0 else "%.1f \u0e1b\u0e35" % yrs))
    stance, head, watch = "mid", "\u0e23\u0e32\u0e04\u0e32\u0e21\u0e35 premium \u0e40\u0e2b\u0e19\u0e37\u0e2d\u0e40\u0e2a\u0e49\u0e19\u0e2d\u0e49\u0e32\u0e07\u0e2d\u0e34\u0e07\u0e1e\u0e2d\u0e1b\u0e23\u0e30\u0e21\u0e32\u0e13", ""
    y40 = ladder[40]
    if y40 is not None and y40 < 1.0:
        stance, head = "good", "\u0e23\u0e32\u0e04\u0e32\u0e43\u0e01\u0e25\u0e49\u0e40\u0e2a\u0e49\u0e19\u0e2d\u0e49\u0e32\u0e07\u0e2d\u0e34\u0e07 \u2014 \u0e41\u0e21\u0e49\u0e01\u0e33\u0e44\u0e23\u0e42\u0e15\u0e23\u0e30\u0e14\u0e31\u0e1a\u0e1b\u0e32\u0e19\u0e01\u0e25\u0e32\u0e07\u0e01\u0e47 \"\u0e42\u0e15\u0e17\u0e31\u0e19\" \u0e20\u0e32\u0e22\u0e43\u0e19\u0e44\u0e21\u0e48\u0e16\u0e36\u0e07\u0e1b\u0e35"
    elif y40 is not None and y40 > 2.5:
        stance, head = "bad", "\u0e23\u0e32\u0e04\u0e32\u0e41\u0e1e\u0e07\u0e40\u0e17\u0e35\u0e22\u0e1a\u0e40\u0e2a\u0e49\u0e19\u0e2d\u0e49\u0e32\u0e07\u0e2d\u0e34\u0e07 \u2014 \u0e15\u0e49\u0e2d\u0e07\u0e42\u0e15\u0e40\u0e23\u0e47\u0e27\u0e15\u0e48\u0e2d\u0e40\u0e19\u0e37\u0e48\u0e2d\u0e07\u0e2b\u0e25\u0e32\u0e22\u0e1b\u0e35\u0e08\u0e36\u0e07\u0e08\u0e30 \"\u0e42\u0e15\u0e17\u0e31\u0e19\""
        watch = "\u0e15\u0e34\u0e14\u0e15\u0e32\u0e21\u0e27\u0e48\u0e32\u0e01\u0e32\u0e23\u0e40\u0e15\u0e34\u0e1a\u0e42\u0e15\u0e15\u0e32\u0e21\u0e17\u0e35\u0e48\u0e04\u0e32\u0e14\u0e22\u0e31\u0e07\u0e44\u0e1b\u0e15\u0e48\u0e2d\u0e44\u0e14\u0e49\u0e2b\u0e23\u0e37\u0e2d\u0e44\u0e21\u0e48 \u0e23\u0e32\u0e04\u0e32\u0e44\u0e27\u0e15\u0e48\u0e2d\u0e01\u0e32\u0e23\u0e17\u0e1a\u0e17\u0e27\u0e19\u0e1b\u0e23\u0e30\u0e21\u0e32\u0e13\u0e01\u0e32\u0e23"
    return _lens(key, title, stance, head, rows,
                 note="\u0e40\u0e2a\u0e49\u0e19\u0e2d\u0e49\u0e32\u0e07\u0e2d\u0e34\u0e07 = P/E \u0e02\u0e2d\u0e07\u0e01\u0e34\u0e08\u0e01\u0e32\u0e23\u0e17\u0e35\u0e48\u0e44\u0e21\u0e48\u0e42\u0e15\u0e40\u0e25\u0e22\u0e43\u0e2b\u0e49\u0e1c\u0e25\u0e15\u0e2d\u0e1a\u0e41\u0e17\u0e19\u0e40\u0e17\u0e48\u0e32\u0e1e\u0e31\u0e19\u0e18\u0e1a\u0e31\u0e15\u0e23 (\u0e01\u0e0e\u0e2b\u0e31\u0e27\u0e41\u0e21\u0e48\u0e21\u0e37\u0e2d) \u00b7 \u0e2a\u0e21\u0e21\u0e15\u0e34\u0e23\u0e32\u0e04\u0e32\u0e2b\u0e38\u0e49\u0e19\u0e04\u0e07\u0e17\u0e35\u0e48 \u0e44\u0e21\u0e48\u0e43\u0e0a\u0e48\u0e01\u0e32\u0e23\u0e17\u0e33\u0e19\u0e32\u0e22\u0e23\u0e32\u0e04\u0e32", watch=watch, data={"pe": pe, "base": base, "ratio": ratio, "ladder": ladder, "tnx": tnx})


