# \u0e40\u0e25\u0e19\u0e2a\u0e4c\u0e17\u0e35\u0e48 7 \u2014 \u0e1b\u0e23\u0e30\u0e27\u0e31\u0e15\u0e34\u0e17\u0e33\u0e40\u0e01\u0e34\u0e19\u0e04\u0e32\u0e14
# ---------------------------------------------------------------
def lens_surprise(D):
    key, title = "surprise", "\u0e1b\u0e23\u0e30\u0e27\u0e31\u0e15\u0e34\u0e17\u0e33\u0e40\u0e01\u0e34\u0e19\u0e04\u0e32\u0e14 \u2014 \u0e22\u0e49\u0e2d\u0e19\u0e2b\u0e25\u0e31\u0e07\u0e23\u0e32\u0e22\u0e07\u0e32\u0e19\u0e14\u0e35\u0e01\u0e27\u0e48\u0e32\u0e17\u0e35\u0e48\u0e04\u0e32\u0e14\u0e44\u0e2b\u0e21"
    ed = D.get("ed")
    if ed is None or getattr(ed, "empty", True) or "Surprise(%)" not in ed.columns:
        return _na(key, title, "\u0e44\u0e21\u0e48\u0e21\u0e35\u0e1b\u0e23\u0e30\u0e27\u0e31\u0e15\u0e34\u0e40\u0e17\u0e35\u0e22\u0e1a\u0e1b\u0e23\u0e30\u0e21\u0e32\u0e13\u0e01\u0e32\u0e23")
    e = ed[ed["Surprise(%)"].notna()].copy()
    try:
        e = e.sort_index(ascending=False)
    except Exception:
        pass
    e = e.head(8)
    if len(e) < 3:
        return _na(key, title, "\u0e1b\u0e23\u0e30\u0e27\u0e31\u0e15\u0e34\u0e2a\u0e31\u0e49\u0e19\u0e40\u0e01\u0e34\u0e19\u0e44\u0e1b")
    s = [float(v) for v in e["Surprise(%)"]]
    beats = sum(1 for v in s if v > 0)
    avg = sum(s) / len(s)
    rows = [("\u0e23\u0e32\u0e22\u0e07\u0e32\u0e19\u0e14\u0e35\u0e01\u0e27\u0e48\u0e32\u0e04\u0e32\u0e14", "%d \u0e08\u0e32\u0e01 %d \u0e44\u0e15\u0e23\u0e21\u0e32\u0e2a\u0e25\u0e48\u0e32\u0e2a\u0e38\u0e14" % (beats, len(s))), ("\u0e2a\u0e48\u0e27\u0e19\u0e40\u0e01\u0e34\u0e19\u0e40\u0e09\u0e25\u0e35\u0e48\u0e22", _pct(avg, 1, True)), ("\u0e44\u0e15\u0e23\u0e21\u0e32\u0e2a\u0e25\u0e48\u0e32\u0e2a\u0e38\u0e14", _pct(s[0], 1, True))]
    stance, head, watch = "mid", "\u0e1c\u0e25\u0e07\u0e32\u0e19\u0e40\u0e17\u0e35\u0e22\u0e1a\u0e1b\u0e23\u0e30\u0e21\u0e32\u0e13\u0e01\u0e32\u0e23\u0e2a\u0e25\u0e31\u0e1a\u0e14\u0e35\u0e2a\u0e25\u0e31\u0e1a\u0e1e\u0e25\u0e32\u0e14", ""
    if beats / len(s) >= 0.75 and avg > 0:
        stance, head = "good", "\u0e2a\u0e48\u0e27\u0e19\u0e43\u0e2b\u0e0d\u0e48\u0e23\u0e32\u0e22\u0e07\u0e32\u0e19\u0e14\u0e35\u0e01\u0e27\u0e48\u0e32\u0e17\u0e35\u0e48\u0e04\u0e32\u0e14"
        watch = "\u0e16\u0e49\u0e32\u0e14\u0e35\u0e01\u0e27\u0e48\u0e32\u0e04\u0e32\u0e14\u0e40\u0e1b\u0e47\u0e19\u0e1b\u0e23\u0e30\u0e08\u0e33 \u0e15\u0e25\u0e32\u0e14\u0e08\u0e30\u0e15\u0e31\u0e49\u0e07\u0e1a\u0e32\u0e23\u0e4c\u0e2a\u0e39\u0e07\u0e02\u0e36\u0e49\u0e19 \u0e02\u0e48\u0e32\u0e27\u0e14\u0e35\u0e40\u0e25\u0e22\u0e2d\u0e32\u0e08 \"\u0e23\u0e32\u0e04\u0e32\u0e23\u0e31\u0e1a\u0e23\u0e39\u0e49\u0e44\u0e1b\u0e41\u0e25\u0e49\u0e27\""
    elif beats / len(s) <= 0.4:
        stance, head = "bad", "\u0e21\u0e31\u0e01\u0e23\u0e32\u0e22\u0e07\u0e32\u0e19\u0e15\u0e48\u0e33\u0e01\u0e27\u0e48\u0e32\u0e17\u0e35\u0e48\u0e04\u0e32\u0e14"
    return _lens(key, title, stance, head, rows, note="\u0e23\u0e32\u0e04\u0e32\u0e2b\u0e38\u0e49\u0e19\u0e15\u0e2d\u0e1a\u0e2a\u0e19\u0e2d\u0e07\u0e15\u0e48\u0e2d \"\u0e04\u0e27\u0e32\u0e21\u0e15\u0e48\u0e32\u0e07\u0e08\u0e32\u0e01\u0e17\u0e35\u0e48\u0e15\u0e25\u0e32\u0e14\u0e04\u0e32\u0e14\" \u0e21\u0e32\u0e01\u0e01\u0e27\u0e48\u0e32\u0e15\u0e31\u0e27\u0e40\u0e25\u0e02\u0e14\u0e35\u0e2b\u0e23\u0e37\u0e2d\u0e41\u0e22\u0e48\u0e43\u0e19\u0e15\u0e31\u0e27\u0e21\u0e31\u0e19\u0e40\u0e2d\u0e07", watch=watch, data={"beats": beats, "n": len(s), "avg": avg, "last": s[0]})


LENSES = [lens_quality, lens_margin, lens_forward, lens_cash, lens_cycle, lens_valuation, lens_surprise]


def build_lenses(D):
    out = []
    for fn in LENSES:
        try:
            out.append(fn(D))
        except Exception as ex:  # \u0e40\u0e25\u0e19\u0e2a\u0e4c\u0e43\u0e14\u0e1e\u0e25\u0e32\u0e14\u0e44\u0e21\u0e48\u0e17\u0e33\u0e43\u0e2b\u0e49\u0e17\u0e31\u0e49\u0e07\u0e2b\u0e19\u0e49\u0e32\u0e25\u0e49\u0e21
            out.append(_na(fn.__name__.replace("lens_", ""), fn.__name__, "\u0e04\u0e33\u0e19\u0e27\u0e13\u0e44\u0e21\u0e48\u0e2a\u0e33\u0e40\u0e23\u0e47\u0e08: %s" % ex))
    return out


def overall(lenses):
    n = {"good": 0, "mid": 0, "bad": 0, "na": 0}
    for l in lenses:
        n[l["stance"]] += 1
    used = n["good"] + n["mid"] + n["bad"]
    goods = [l["title"].split(" \u2014 ")[0] for l in lenses if l["stance"] == "good"]
    bads = [l["title"].split(" \u2014 ")[0] for l in lenses if l["stance"] == "bad"]
    if used == 0:
        return n, "\u0e02\u0e49\u0e2d\u0e21\u0e39\u0e25\u0e44\u0e21\u0e48\u0e1e\u0e2d\u0e17\u0e35\u0e48\u0e08\u0e30\u0e2a\u0e23\u0e38\u0e1b\u0e08\u0e32\u0e01\u0e2b\u0e25\u0e32\u0e22\u0e21\u0e38\u0e21", MUTED, ""
    if n["good"] and n["bad"]:
        lab, col = "\u0e21\u0e38\u0e21\u0e21\u0e2d\u0e07\u0e02\u0e31\u0e14\u0e01\u0e31\u0e19", YELLOW
        txt = "\u0e14\u0e35: %s \u00b7 \u0e04\u0e27\u0e23\u0e23\u0e30\u0e27\u0e31\u0e07: %s \u2014 \u0e15\u0e31\u0e27\u0e40\u0e25\u0e02\u0e0a\u0e38\u0e14\u0e40\u0e14\u0e35\u0e22\u0e27\u0e01\u0e31\u0e19\u0e43\u0e2b\u0e49\u0e02\u0e49\u0e2d\u0e2a\u0e23\u0e38\u0e1b\u0e15\u0e48\u0e32\u0e07\u0e01\u0e31\u0e19\u0e15\u0e32\u0e21\u0e21\u0e38\u0e21\u0e17\u0e35\u0e48\u0e43\u0e0a\u0e49 \u0e04\u0e27\u0e23\u0e2d\u0e48\u0e32\u0e19\u0e04\u0e27\u0e1a\u0e04\u0e39\u0e48\u0e01\u0e31\u0e19\u0e01\u0e48\u0e2d\u0e19\u0e2a\u0e23\u0e38\u0e1b" % (", ".join(goods), ", ".join(bads))
    elif n["bad"] >= 2 or (n["bad"] and not n["good"]):
        lab, col, txt = "\u0e2a\u0e48\u0e27\u0e19\u0e43\u0e2b\u0e0d\u0e48\u0e0a\u0e35\u0e49\u0e44\u0e1b\u0e17\u0e32\u0e07\u0e23\u0e30\u0e27\u0e31\u0e07", RED, "\u0e21\u0e38\u0e21\u0e17\u0e35\u0e48\u0e40\u0e15\u0e37\u0e2d\u0e19: %s" % ", ".join(bads)
    elif n["good"] >= 2 and not n["bad"]:
        lab, col, txt = "\u0e2a\u0e48\u0e27\u0e19\u0e43\u0e2b\u0e0d\u0e48\u0e0a\u0e35\u0e49\u0e44\u0e1b\u0e17\u0e32\u0e07\u0e1a\u0e27\u0e01", GREEN, "\u0e21\u0e38\u0e21\u0e17\u0e35\u0e48\u0e40\u0e1b\u0e47\u0e19\u0e1a\u0e27\u0e01: %s" % ", ".join(goods)
    else:
        lab, col, txt = "\u0e01\u0e25\u0e32\u0e07\u0e46 / \u0e22\u0e31\u0e07\u0e44\u0e21\u0e48\u0e0a\u0e31\u0e14", YELLOW, "\u0e22\u0e31\u0e07\u0e44\u0e21\u0e48\u0e21\u0e35\u0e21\u0e38\u0e21\u0e44\u0e2b\u0e19\u0e40\u0e14\u0e48\u0e19\u0e0a\u0e31\u0e14\u0e17\u0e31\u0e49\u0e07\u0e1a\u0e27\u0e01\u0e41\u0e25\u0e30\u0e25\u0e1a"
    return n, lab, col, txt


