                chips = '<div class="in-ez-hz">%s</div>' % "".join('<span style="--pc:%s"><em>%s</em>%s</span>' % (cmap.get(v_, MUTED), n_, v_) for n_, v_ in zip(("\u0e23\u0e30\u0e22\u0e30\u0e2a\u0e31\u0e49\u0e19", "\u0e23\u0e30\u0e22\u0e30\u0e01\u0e25\u0e32\u0e07", "\u0e23\u0e30\u0e22\u0e30\u0e22\u0e32\u0e27"), mm.groups()))
