_LOG_PATH = os.path.join(os.path.dirname(os.path.abspath(__file__)), "quant_insight_log.json")
_LB = {"good": "\u0e1a\u0e27\u0e01", "mid": "\u0e01\u0e25\u0e32\u0e07\u0e46", "bad": "\u0e23\u0e30\u0e27\u0e31\u0e07", "na": "\u0e02\u0e49\u0e2d\u0e21\u0e39\u0e25\u0e44\u0e21\u0e48\u0e1e\u0e2d"}


def _log_read():
    try:
        with open(_LOG_PATH, encoding="utf-8") as f:
            d = json.load(f)
        return d if isinstance(d, dict) else {}
    except Exception:
        return {}


def log_and_diff(sym, m):
    """\u0e1a\u0e31\u0e19\u0e17\u0e36\u0e01\u0e2a\u0e23\u0e38\u0e1b\u0e27\u0e31\u0e19\u0e19\u0e35\u0e49 (\u0e44\u0e1f\u0e25\u0e4c\u0e40\u0e14\u0e35\u0e22\u0e27\u0e15\u0e48\u0e2d\u0e2b\u0e38\u0e49\u0e19 \u0e27\u0e31\u0e19\u0e25\u0e30 1 \u0e23\u0e32\u0e22\u0e01\u0e32\u0e23) \u0e41\u0e25\u0e49\u0e27\u0e40\u0e17\u0e35\u0e22\u0e1a\u0e01\u0e31\u0e1a\u0e04\u0e23\u0e31\u0e49\u0e07\u0e01\u0e48\u0e2d\u0e19\u0e2b\u0e19\u0e49\u0e32 \u00b7 \u0e1e\u0e25\u0e32\u0e14 (\u0e40\u0e0a\u0e48\u0e19\u0e40\u0e02\u0e35\u0e22\u0e19\u0e44\u0e1f\u0e25\u0e4c\u0e44\u0e21\u0e48\u0e44\u0e14\u0e49) = \u0e02\u0e49\u0e32\u0e21\u0e40\u0e07\u0e35\u0e22\u0e1a\u0e46"""
    today = _dt.date.today().isoformat()
    sig = m["sig"]
    entry = {"date": today, "verdict": m["verdict"], "biz": sig["biz"], "price": sig["price"], "timing": sig["timing"],
             "quality": None if not _ok(sig.get("quality")) else round(float(sig["quality"]), 1),
             "px": None if not _ok(sig.get("px")) else round(float(sig["px"]), 2)}
    data = _log_read()
    hist = [x for x in data.get(sym, []) if isinstance(x, dict) and x.get("date")]
    prev = [x for x in hist if x["date"] < today]
    hist = [x for x in hist if x["date"] != today] + [entry]
    data[sym] = hist[-120:]
    try:
        with open(_LOG_PATH, "w", encoding="utf-8") as f:
            json.dump(data, f, ensure_ascii=False)
    except Exception:
        pass
    return entry, (prev[-1] if prev else None), prev


def _diff_html(sym, entry, prev, allprev):
    if not prev:
        return ('<div class="ms-df"><b>\U0001f504 \u0e40\u0e17\u0e35\u0e22\u0e1a\u0e01\u0e31\u0e1a\u0e04\u0e23\u0e31\u0e49\u0e07\u0e01\u0e48\u0e2d\u0e19:</b> \u0e40\u0e23\u0e34\u0e48\u0e21\u0e40\u0e01\u0e47\u0e1a\u0e1a\u0e31\u0e19\u0e17\u0e36\u0e01\u0e02\u0e2d\u0e07 %s \u0e27\u0e31\u0e19\u0e19\u0e35\u0e49 \u2014 \u0e40\u0e1b\u0e34\u0e14\u0e2b\u0e19\u0e49\u0e32\u0e19\u0e35\u0e49\u0e2d\u0e35\u0e01\u0e04\u0e23\u0e31\u0e49\u0e07\u0e43\u0e19\u0e27\u0e31\u0e19\u0e16\u0e31\u0e14\u0e44\u0e1b \u0e23\u0e30\u0e1a\u0e1a\u0e08\u0e30\u0e1a\u0e2d\u0e01\u0e27\u0e48\u0e32\u0e2d\u0e30\u0e44\u0e23\u0e40\u0e1b\u0e25\u0e35\u0e48\u0e22\u0e19\u0e44\u0e1b</div>') % _e(sym)
    try:
        days = (_dt.date.fromisoformat(entry["date"]) - _dt.date.fromisoformat(prev["date"])).days
    except Exception:
        days = None
    ch = []
    for k, nm in (("biz", "\u0e18\u0e38\u0e23\u0e01\u0e34\u0e08"), ("price", "\u0e23\u0e32\u0e04\u0e32"), ("timing", "\u0e08\u0e31\u0e07\u0e2b\u0e27\u0e30\u0e23\u0e32\u0e04\u0e32")):
        if prev.get(k) != entry.get(k):
            ch.append("%s: %s \u2192 %s" % (nm, _LB.get(prev.get(k), "\u2014"), _LB.get(entry.get(k), "\u2014")))
    q0, q1 = prev.get("quality"), entry.get("quality")
    if _ok(q0) and _ok(q1) and abs(q1 - q0) >= 3:
        ch.append("\u0e04\u0e30\u0e41\u0e19\u0e19\u0e04\u0e38\u0e13\u0e20\u0e32\u0e1e %.0f \u2192 %.0f" % (q0, q1))
    p0, p1 = prev.get("px"), entry.get("px")
    mv_t = ""
    if _ok(p0) and _ok(p1) and p0:
        mv_t = " \u00b7 \u0e23\u0e32\u0e04\u0e32 %s \u0e14\u0e2d\u0e25\u0e25\u0e32\u0e23\u0e4c (%s \u0e08\u0e32\u0e01\u0e04\u0e23\u0e31\u0e49\u0e07\u0e01\u0e48\u0e2d\u0e19)" % (format(p1, ",.2f"), _pct((p1 / p0 - 1) * 100, 1, True))
    head = "\U0001f504 \u0e40\u0e17\u0e35\u0e22\u0e1a\u0e01\u0e31\u0e1a\u0e04\u0e23\u0e31\u0e49\u0e07\u0e01\u0e48\u0e2d\u0e19 (%s%s)" % (prev["date"], (", %d \u0e27\u0e31\u0e19\u0e01\u0e48\u0e2d\u0e19" % days) if days is not None else "")
    body = "; ".join(ch) if ch else "\u0e44\u0e1f\u0e17\u0e31\u0e49\u0e07 3 \u0e14\u0e27\u0e07\u0e40\u0e2b\u0e21\u0e37\u0e2d\u0e19\u0e40\u0e14\u0e34\u0e21"
    return '<div class="ms-df"><b>%s:</b> %s%s</div>' % (_e(head), _e(body), _e(mv_t))


def _history_rows(allprev, entry):
    """\u0e15\u0e23\u0e27\u0e08\u0e22\u0e49\u0e2d\u0e19: \u0e2a\u0e23\u0e38\u0e1b\u0e40\u0e01\u0e48\u0e32\u0e46 \u0e15\u0e2d\u0e19\u0e19\u0e31\u0e49\u0e19\u0e44\u0e1f\u0e40\u0e1b\u0e47\u0e19\u0e2d\u0e30\u0e44\u0e23 \u0e41\u0e25\u0e30\u0e23\u0e32\u0e04\u0e32\u0e2b\u0e25\u0e31\u0e07\u0e08\u0e32\u0e01\u0e19\u0e31\u0e49\u0e19\u0e02\u0e22\u0e31\u0e1a\u0e40\u0e17\u0e48\u0e32\u0e44\u0e23 (\u0e41\u0e2a\u0e14\u0e07\u0e02\u0e49\u0e2d\u0e40\u0e17\u0e47\u0e08\u0e08\u0e23\u0e34\u0e07 \u0e44\u0e21\u0e48\u0e44\u0e14\u0e49\u0e1f\u0e31\u0e19\u0e18\u0e07\u0e27\u0e48\u0e32\u0e2a\u0e23\u0e38\u0e1b\u0e16\u0e39\u0e01\u0e2b\u0e23\u0e37\u0e2d\u0e1c\u0e34\u0e14)"""
    rows = []
    for x in allprev[-8:][::-1]:
        if _ok(x.get("px")) and _ok(entry.get("px")) and x["px"]:
            rows.append("%s \u00b7 \u0e18\u0e38\u0e23\u0e01\u0e34\u0e08%s / \u0e23\u0e32\u0e04\u0e32%s / \u0e08\u0e31\u0e07\u0e2b\u0e27\u0e30%s \u00b7 \u0e23\u0e32\u0e04\u0e32 %s \u2192 \u0e27\u0e31\u0e19\u0e19\u0e35\u0e49 %s (%s)" % (
                x["date"], _LB.get(x.get("biz"), "\u2014"), _LB.get(x.get("price"), "\u2014"), _LB.get(x.get("timing"), "\u2014"),
                format(x["px"], ",.2f"), format(entry["px"], ",.2f"), _pct((entry["px"] / x["px"] - 1) * 100, 1, True)))
    return rows


def _about_lines(D):
    """\u0e22\u0e48\u0e2d\u0e2b\u0e19\u0e49\u0e32 "\u0e1a\u0e23\u0e34\u0e29\u0e31\u0e17\u0e17\u0e33\u0e2d\u0e30\u0e44\u0e23" \u0e08\u0e32\u0e01\u0e02\u0e49\u0e2d\u0e21\u0e39\u0e25 Yahoo (\u0e41\u0e1b\u0e25\u0e44\u0e17\u0e22\u0e1f\u0e23\u0e35 \u0e16\u0e49\u0e32\u0e41\u0e1b\u0e25\u0e44\u0e21\u0e48\u0e44\u0e14\u0e49\u0e08\u0e30\u0e41\u0e2a\u0e14\u0e07\u0e40\u0e09\u0e1e\u0e32\u0e30\u0e02\u0e49\u0e2d\u0e21\u0e39\u0e25\u0e2a\u0e31\u0e49\u0e19\u0e46 \u0e17\u0e35\u0e48\u0e40\u0e1b\u0e47\u0e19\u0e02\u0e49\u0e2d\u0e40\u0e17\u0e47\u0e08\u0e08\u0e23\u0e34\u0e07)"""
    info = (D or {}).get("info") or {}
    out = []
    try:
        sm_ = (info.get("longBusinessSummary") or "").strip()
        if sm_:
            sents = re.split(r"(?<=[.!?])\s+", sm_)
            short = " ".join(sents[:2])[:420]
            th = None
            try:
                import news_feed
                th = tr_list([short])
                th = (th[0] if th else "") or None
            except Exception:
                th = None
            if th and th != short:
                out.append(th.strip())
        facts = []
        if info.get("sector"):
            facts.append("\u0e01\u0e25\u0e38\u0e48\u0e21: %s%s" % (info["sector"], (" / " + info["industry"]) if info.get("industry") else ""))
        loc = ", ".join(x for x in (info.get("city"), info.get("state"), info.get("country")) if x)
        if loc:
            facts.append("\u0e2a\u0e33\u0e19\u0e31\u0e01\u0e07\u0e32\u0e19\u0e43\u0e2b\u0e0d\u0e48: " + loc)
        if info.get("fullTimeEmployees"):
            facts.append("\u0e1e\u0e19\u0e31\u0e01\u0e07\u0e32\u0e19: %s \u0e04\u0e19" % format(int(info["fullTimeEmployees"]), ","))
        if info.get("marketCap"):
            facts.append("\u0e21\u0e39\u0e25\u0e04\u0e48\u0e32\u0e15\u0e25\u0e32\u0e14: %s" % _money(info["marketCap"]))
        lo, hi = info.get("fiftyTwoWeekLow"), info.get("fiftyTwoWeekHigh")
        if lo and hi:
            facts.append("\u0e0a\u0e48\u0e27\u0e07\u0e23\u0e32\u0e04\u0e32 52 \u0e2a\u0e31\u0e1b\u0e14\u0e32\u0e2b\u0e4c: %s - %s \u0e14\u0e2d\u0e25\u0e25\u0e32\u0e23\u0e4c" % (format(lo, ",.2f"), format(hi, ",.2f")))
        out += ["- " + f for f in facts]
    except Exception:
        pass
    return out


def build_article(sym, D, m, sm, mv, pr):
    """\u0e1a\u0e17\u0e04\u0e27\u0e32\u0e21\u0e2a\u0e23\u0e38\u0e1b\u0e40\u0e1b\u0e47\u0e19\u0e02\u0e49\u0e2d\u0e04\u0e27\u0e32\u0e21\u0e25\u0e49\u0e27\u0e19 \u0e2d\u0e48\u0e32\u0e19\u0e23\u0e39\u0e49\u0e40\u0e23\u0e37\u0e48\u0e2d\u0e07\u0e40\u0e2d\u0e07\u0e42\u0e14\u0e22\u0e44\u0e21\u0e48\u0e15\u0e49\u0e2d\u0e07\u0e40\u0e2b\u0e47\u0e19\u0e40\u0e27\u0e47\u0e1a (\u0e04\u0e31\u0e14\u0e25\u0e2d\u0e01\u0e44\u0e1b\u0e27\u0e32\u0e07\u0e41\u0e0a\u0e17/\u0e42\u0e1e\u0e2a\u0e15\u0e4c\u0e44\u0e14\u0e49) \u00b7 \u0e2d\u0e18\u0e34\u0e1a\u0e32\u0e22\u0e04\u0e33\u0e28\u0e31\u0e1e\u0e17\u0e4c\u0e17\u0e49\u0e32\u0e22\u0e1a\u0e17\u0e04\u0e27\u0e32\u0e21 \u00b7 \u0e44\u0e21\u0e48\u0e43\u0e0a\u0e49\u0e2a\u0e31\u0e0d\u0e25\u0e31\u0e01\u0e29\u0e13\u0e4c\u0e14\u0e2d\u0e25\u0e25\u0e32\u0e23\u0e4c"""
    ps, rt, t = (tuple(pr) + (None, None, None))[:3] if pr else (None, None, None)
    d = (mv or {}).get("date") or _dt.date.today()
    try:
        ds = "%d %s %d" % (d.day, _TH_MON[d.month - 1], d.year + 543)
    except Exception:
        ds = str(d)
    nm = lambda s_: STANCE.get(s_, ("-", ""))[0]
    sc = lambda x: re.sub(r"\s*\((\d{1,3})\)\s*$", lambda mm: " (\u0e04\u0e30\u0e41\u0e19\u0e19 %s \u0e08\u0e32\u0e01 100)" % mm.group(1), x)
    L = []
    BAR = "\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501"
    L.append("\U0001f4c8 \u0e2a\u0e23\u0e38\u0e1b\u0e2b\u0e38\u0e49\u0e19 %s (%s)" % (m["name"], sym))
    L.append("\u0e02\u0e49\u0e2d\u0e21\u0e39\u0e25 \u0e13 %s" % ds)
    L += ["", BAR, "\U0001f4cc \u0e2a\u0e23\u0e38\u0e1b 30 \u0e27\u0e34\u0e19\u0e32\u0e17\u0e35", BAR, m["verdict"]]
    _l3 = [(ttl, nm(st_)) for ttl, st_, _t in m["lights"]]
    if _l3:
        L.append(" \u00b7 ".join("%s: %s" % x for x in _l3))
    ab = _about_lines(D)
    if ab:
        L += ["", BAR, "\U0001f3e2 \u0e1a\u0e23\u0e34\u0e29\u0e31\u0e17\u0e19\u0e35\u0e49\u0e17\u0e33\u0e2d\u0e30\u0e44\u0e23", BAR] + ab
    # ---- \u0e40\u0e01\u0e34\u0e14\u0e2d\u0e30\u0e44\u0e23\u0e02\u0e36\u0e49\u0e19\u0e01\u0e31\u0e1a\u0e23\u0e32\u0e04\u0e32 ----
    if m.get("today"):
        L += ["", BAR, "\U0001f4f0 \u0e27\u0e31\u0e19\u0e19\u0e35\u0e49\u0e40\u0e01\u0e34\u0e14\u0e2d\u0e30\u0e44\u0e23\u0e02\u0e36\u0e49\u0e19", BAR, m["today"]]
        if m.get("market"):
            L.append("\u0e20\u0e32\u0e1e\u0e15\u0e25\u0e32\u0e14\u0e23\u0e27\u0e21: " + m["market"])
    evs_ = (mv or {}).get("_events") or []
    if evs_:
        L += ["", "\U0001f552 \u0e17\u0e35\u0e48\u0e1c\u0e48\u0e32\u0e19\u0e21\u0e32 (\u0e27\u0e31\u0e19\u0e17\u0e35\u0e48\u0e23\u0e32\u0e04\u0e32\u0e02\u0e22\u0e31\u0e1a\u0e41\u0e23\u0e07\u0e1c\u0e34\u0e14\u0e1b\u0e01\u0e15\u0e34\u0e43\u0e19 1 \u0e40\u0e14\u0e37\u0e2d\u0e19\u0e25\u0e48\u0e32\u0e2a\u0e38\u0e14)"]
        for e in evs_:
            dd_ = e["date"]
            line = "- %d %s: \u0e23\u0e32\u0e04\u0e32%s %s (%s)" % (dd_.day, _TH_MON[dd_.month - 1], "\u0e25\u0e07" if e["chg"] < 0 else "\u0e02\u0e36\u0e49\u0e19", _pct(abs(e["chg"]), 1), e.get("chip") or "")
            if e.get("themed") and e.get("head"):
                line += " \u0e02\u0e48\u0e32\u0e27\u0e23\u0e2d\u0e1a\u0e27\u0e31\u0e19\u0e19\u0e31\u0e49\u0e19: " + e["head"]
            else:
                line += " \u0e22\u0e31\u0e07\u0e44\u0e21\u0e48\u0e1e\u0e1a\u0e02\u0e48\u0e32\u0e27\u0e17\u0e35\u0e48\u0e0a\u0e35\u0e49\u0e0a\u0e31\u0e14\u0e27\u0e48\u0e32\u0e40\u0e1b\u0e47\u0e19\u0e2a\u0e32\u0e40\u0e2b\u0e15\u0e38"
            L.append(line)
    try:
        story = st.session_state.get("in_story_%s_%s" % (sym, (mv or {}).get("date")))
    except Exception:
        story = None
    if story and story.get("text"):
        L += ["", "\u0e40\u0e23\u0e37\u0e48\u0e2d\u0e07\u0e23\u0e32\u0e27\u0e08\u0e32\u0e01\u0e02\u0e48\u0e32\u0e27 (AI \u0e04\u0e49\u0e19\u0e40\u0e27\u0e47\u0e1a%s)" % ("" if story.get("searched") else " \u0e2a\u0e23\u0e38\u0e1b\u0e08\u0e32\u0e01\u0e2b\u0e31\u0e27\u0e02\u0e49\u0e2d\u0e02\u0e48\u0e32\u0e27 \u0e44\u0e21\u0e48\u0e44\u0e14\u0e49\u0e04\u0e49\u0e19\u0e40\u0e27\u0e47\u0e1a"), story["text"].strip()]
        if story.get("sources"):
            L.append("\u0e41\u0e2b\u0e25\u0e48\u0e07\u0e2d\u0e49\u0e32\u0e07\u0e2d\u0e34\u0e07: " + " | ".join(x["url"] for x in story["sources"][:4]))
    try:
        tl_ = st.session_state.get("in_tl_%s_%s" % (sym, (mv or {}).get("date")))
    except Exception:
        tl_ = None
    if tl_ and tl_.get("text"):
        L += ["", "\u0e44\u0e17\u0e21\u0e4c\u0e44\u0e25\u0e19\u0e4c\u0e40\u0e2b\u0e15\u0e38\u0e01\u0e32\u0e23\u0e13\u0e4c\u0e2a\u0e33\u0e04\u0e31\u0e0d (AI \u0e04\u0e49\u0e19\u0e40\u0e27\u0e47\u0e1a)", tl_["text"].strip()]
    # ---- \u0e15\u0e31\u0e27\u0e18\u0e38\u0e23\u0e01\u0e34\u0e08\u0e41\u0e25\u0e30\u0e23\u0e32\u0e04\u0e32 ----
    L += ["", BAR, "\U0001f9ed \u0e20\u0e32\u0e1e\u0e23\u0e27\u0e21 3 \u0e14\u0e49\u0e32\u0e19", "(\u0e1a\u0e27\u0e01 = \u0e2a\u0e31\u0e0d\u0e0d\u0e32\u0e13\u0e14\u0e35 \u00b7 \u0e01\u0e25\u0e32\u0e07\u0e46 = \u0e22\u0e31\u0e07\u0e44\u0e21\u0e48\u0e0a\u0e31\u0e14 \u00b7 \u0e23\u0e30\u0e27\u0e31\u0e07 = \u0e2a\u0e31\u0e0d\u0e0d\u0e32\u0e13\u0e44\u0e21\u0e48\u0e14\u0e35)", BAR]
    for ttl, st_, txt in m["lights"]:
        L.append("- %s: %s. %s" % (ttl, nm(st_), sc(txt)))
    cf = m.get("conf")
    if cf:
        L.append("- \u0e04\u0e27\u0e32\u0e21\u0e19\u0e48\u0e32\u0e40\u0e0a\u0e37\u0e48\u0e2d\u0e16\u0e37\u0e2d\u0e02\u0e2d\u0e07\u0e02\u0e49\u0e2d\u0e21\u0e39\u0e25: %s. %s" % ({"good": "\u0e2a\u0e39\u0e07", "mid": "\u0e1b\u0e32\u0e19\u0e01\u0e25\u0e32\u0e07", "bad": "\u0e15\u0e48\u0e33"}[cf["level"]], " ".join(x.rstrip(".") + "." for x in cf["why"])))
    if m["good"]:
        L += ["", "\U0001f4aa \u0e08\u0e38\u0e14\u0e41\u0e02\u0e47\u0e07 (\u0e15\u0e31\u0e27\u0e40\u0e25\u0e02\u0e43\u0e19\u0e27\u0e07\u0e40\u0e25\u0e47\u0e1a\u0e04\u0e37\u0e2d\u0e04\u0e30\u0e41\u0e19\u0e19\u0e17\u0e35\u0e48\u0e23\u0e30\u0e1a\u0e1a\u0e43\u0e2b\u0e49 0-100 \u0e22\u0e34\u0e48\u0e07\u0e2a\u0e39\u0e07\u0e22\u0e34\u0e48\u0e07\u0e14\u0e35)"] + ["- " + sc(x) for x in m["good"]]
    if m["warn"]:
        L += ["", "\u26a0\ufe0f \u0e04\u0e27\u0e23\u0e23\u0e30\u0e27\u0e31\u0e07"] + ["- " + sc(x) for x in m["warn"]]
