ETF_OVERRIDE = {"SNDK": "SOXX", "WDC": "SOXX", "STX": "SOXX", "MU": "SOXX", "PSTG": "SOXX", "NTAP": "SOXX", "MRVL": "SOXX"}


def _sector_etf(info, sym=None):
    if sym and sym.upper() in ETF_OVERRIDE:
        return ETF_OVERRIDE[sym.upper()]
    ind = (info.get("industry") or "").lower()
    if "semiconductor" in ind:
        return "SOXX"
    return SECTOR_ETF.get(info.get("sector") or "")


@st.cache_data(ttl=300, show_spinner=False)
def _move_ctx(sym, etf):
    """\u0e04\u0e27\u0e32\u0e21\u0e40\u0e04\u0e25\u0e37\u0e48\u0e2d\u0e19\u0e44\u0e2b\u0e27\u0e25\u0e48\u0e32\u0e2a\u0e38\u0e14\u0e02\u0e2d\u0e07\u0e2b\u0e38\u0e49\u0e19 \u0e40\u0e17\u0e35\u0e22\u0e1a SPY / QQQ / ETF \u0e01\u0e25\u0e38\u0e48\u0e21 \u00b7 \u0e40\u0e1a\u0e15\u0e49\u0e32 \u00b7 \u0e04\u0e27\u0e32\u0e21\u0e1c\u0e34\u0e14\u0e1b\u0e01\u0e15\u0e34 (z) \u00b7 \u0e1b\u0e23\u0e34\u0e21\u0e32\u0e13"""
    uniq = list(dict.fromkeys([sym, "SPY", "QQQ"] + ([etf] if etf else [])))
    try:
        d = yf.download(" ".join(uniq), period="8mo", interval="1d", group_by="ticker", progress=False, auto_adjust=True)
    except Exception:
        return None

    def col(x, field="Close"):
        try:
            v = d[x][field].dropna()
            return v if len(v) else None
        except Exception:
            return None
    c, s = col(sym), col("SPY")
    if c is None or s is None or len(c) < 30:
        return None
    ret, sret = c.pct_change().dropna(), s.pct_change().dropna()
    chg = float(ret.iloc[-1]) * 100
    last = c.index[-1]

    def lastchg(x):
        v = col(x)
        if v is None or len(v) < 3 or v.index[-1] != last:
            return None
        return float(v.pct_change().dropna().iloc[-1]) * 100
    j = pd.concat([ret, sret], axis=1, join="inner").dropna()
    beta = None
    if len(j) >= 60:
        t = j.tail(120)
        var = float(t.iloc[:, 1].var())
        beta = float(t.iloc[:, 0].cov(t.iloc[:, 1]) / var) if var > 0 else None
    std60 = float(ret.iloc[-61:-1].std()) * 100 if len(ret) > 61 else None
    vol = col(sym, "Volume")
    vr = None
    if vol is not None and len(vol) > 21 and float(vol.iloc[-21:-1].mean()) > 0:
        vr = float(vol.iloc[-1]) / float(vol.iloc[-21:-1].mean())
    return {"sym": sym, "date": last.date(), "px": float(c.iloc[-1]), "chg": chg, "spy": lastchg("SPY"), "qqq": lastchg("QQQ"),
            "etf": etf, "sec": lastchg(etf) if etf else None, "beta": beta, "z": (chg / std60 if std60 else None), "vr": vr}


def why_kind(mv):
    """\u0e08\u0e33\u0e41\u0e19\u0e01\u0e27\u0e48\u0e32\u0e01\u0e32\u0e23\u0e02\u0e22\u0e31\u0e1a\u0e27\u0e31\u0e19\u0e19\u0e35\u0e49 '\u0e1b\u0e01\u0e15\u0e34 / \u0e15\u0e32\u0e21\u0e01\u0e25\u0e38\u0e48\u0e21 / \u0e15\u0e32\u0e21\u0e15\u0e25\u0e32\u0e14 / \u0e40\u0e09\u0e1e\u0e32\u0e30\u0e15\u0e31\u0e27' \u0e14\u0e49\u0e27\u0e22\u0e2a\u0e31\u0e14\u0e2a\u0e48\u0e27\u0e19\u0e17\u0e35\u0e48\u0e2d\u0e18\u0e34\u0e1a\u0e32\u0e22\u0e44\u0e14\u0e49"""
    chg, spy, sec, beta, z = mv["chg"], mv.get("spy"), mv.get("sec"), mv.get("beta"), mv.get("z")
    exp_mkt = (beta * spy if beta is not None else spy) if spy is not None else None
    mv["exp_mkt"] = exp_mkt
    same = lambda a, b: a is not None and b is not None and a * b > 0
    if abs(chg) < 2 and (z is None or abs(z) < 1.5):
        return "normal"
    if same(chg, sec) and abs(sec) >= 0.6 * abs(chg):
        return "sector"
    if same(chg, exp_mkt) and abs(exp_mkt) >= 0.6 * abs(chg):
        return "market"
    if same(chg, sec) and abs(sec) >= 0.35 * abs(chg):
        return "sector_plus"
    if same(chg, exp_mkt) and abs(exp_mkt) >= 0.35 * abs(chg):
        return "market_plus"
    return "own"


