@st.cache_data(ttl=600, show_spinner=False)
def _news_for(sym, ai_key, n=5):
    try:
        import news_feed
        feed = news_feed.build_feed((sym,), ai_key or "", 3)          # \u0e1e\u0e32\u0e23\u0e32\u0e21\u0e34\u0e40\u0e15\u0e2d\u0e23\u0e4c\u0e15\u0e31\u0e27\u0e17\u0e35\u0e48 3 = \u0e22\u0e49\u0e2d\u0e19\u0e2b\u0e25\u0e31\u0e07\u0e01\u0e35\u0e48\u0e27\u0e31\u0e19
        items = [x for x in feed.get("feed", []) if x.get("ticker") == sym][:n]
        for x in items:
            try:
                x["ago"] = news_feed.ago(x["ts"]) if x.get("ts") else ""
            except Exception:
                x["ago"] = ""
        return {"items": items, "ai": bool(feed.get("ai")), "overview": (feed.get("per", {}).get(sym, {}) or {}).get("overview", "")}
    except Exception:
        return {"items": [], "ai": False, "overview": ""}


