_THEME_RX = {t[0]: [re.compile(p, re.I) for p in t[2]] for t in THEMES}


def _themes_from(titles):
    out = []
    for key, label, _rx, expl, phrase, watch, w in THEMES:
        idx = [i for i, t in enumerate(titles) if any(r.search(t or "") for r in _THEME_RX[key])]
        if idx:
            out.append({"key": key, "label": label, "expl": expl, "phrase": phrase, "watch": watch, "idx": idx, "score": len(idx) * w})
    out.sort(key=lambda x: -x["score"])
    return out


@st.cache_data(ttl=600, show_spinner=False)
def _why_news(sym, etf, sector, mkt_big):
    """\u0e02\u0e48\u0e32\u0e27\u0e23\u0e30\u0e14\u0e31\u0e1a\u0e01\u0e25\u0e38\u0e48\u0e21/\u0e15\u0e25\u0e32\u0e14 2 \u0e27\u0e31\u0e19\u0e25\u0e48\u0e32\u0e2a\u0e38\u0e14 (Google News RSS) \u0e40\u0e1e\u0e37\u0e48\u0e2d\u0e2b\u0e32\u0e18\u0e35\u0e21\u0e17\u0e35\u0e48\u0e2a\u0e37\u0e48\u0e2d\u0e42\u0e22\u0e07\u0e01\u0e31\u0e1a\u0e01\u0e32\u0e23\u0e02\u0e22\u0e31\u0e1a \u00b7 \u0e41\u0e1b\u0e25\u0e2b\u0e31\u0e27\u0e02\u0e49\u0e2d\u0e40\u0e1b\u0e47\u0e19\u0e44\u0e17\u0e22\u0e1f\u0e23\u0e35"""
    try:
        import news_radar
        import news_feed
    except Exception:
        return {"items": []}
    qs = []
    if etf == "SOXX":
        qs += [("\u0e01\u0e25\u0e38\u0e48\u0e21", "semiconductor stocks when:2d"), ("\u0e01\u0e25\u0e38\u0e48\u0e21", "memory chip stocks selloff when:2d")]
    elif sector:
        qs.append(("\u0e01\u0e25\u0e38\u0e48\u0e21", "%s stocks when:2d" % sector))
    if mkt_big:
        qs.append(("\u0e15\u0e25\u0e32\u0e14", "stock market today when:2d"))
    rows, seen = [], set()
    for tag, q in qs:
        try:
            got = news_radar.fetch_google_news(q, max_items=12) or []
        except Exception:
            got = []
        for n in got:
            t, src = news_feed._clean_title(n.get("title"), n.get("source"))
            k = news_feed._norm(t)
            if not k or k in seen:
                continue
            seen.add(k)
            rows.append({"tag": tag, "title_en": t, "link": n.get("link", ""), "source": src, "ts": news_feed._parse_ts(n.get("pub_date"))})
    rows.sort(key=lambda r: r["ts"].timestamp() if r["ts"] else 0, reverse=True)
    rows = rows[:12]
    for r in rows:
        r["th"] = r["title_en"]
        try:
            r["ago"] = news_feed.ago(r["ts"]) if r["ts"] else ""
        except Exception:
            r["ago"] = ""
        r["ts"] = None
    return {"items": rows}


