def _short_name(name, sym):
    n = (name or "").strip()
    for suf in (", Inc.", " Inc.", " Inc", " Corporation", " Corp.", " Corp", " Company", " Co.", " Ltd.", " Ltd", " plc", " Holdings", " Group"):
        if n.endswith(suf):
            n = n[: -len(suf)].strip(" ,")
    return n or sym


def _top_themes(rows, max_themes=3):
    th = _themes_from([r.get("title_en") or r.get("title") or "" for r in rows])
    main = [t for t in th if t["key"] != "chip_sector"]
    pick = [t for t in main if len(t["idx"]) >= 2][:max_themes]
    for t in main:                                   # \u0e40\u0e15\u0e34\u0e21\u0e43\u0e2b\u0e49\u0e04\u0e23\u0e1a\u0e2d\u0e22\u0e48\u0e32\u0e07\u0e19\u0e49\u0e2d\u0e22 2 \u0e18\u0e35\u0e21\u0e16\u0e49\u0e32\u0e21\u0e35\u0e02\u0e48\u0e32\u0e27\u0e1e\u0e2d
        if len(pick) >= min(2, max_themes):
            break
        if t not in pick:
            pick.append(t)
    if not pick:
        pick = th[:1]
    return pick, th


