@st.cache_data(ttl=900, show_spinner=False)
def _big_days(sym, etf, last_days=32):
    """\u0e27\u0e31\u0e19\u0e17\u0e35\u0e48\u0e2b\u0e38\u0e49\u0e19\u0e02\u0e22\u0e31\u0e1a\u0e1c\u0e34\u0e14\u0e1b\u0e01\u0e15\u0e34\u0e43\u0e19 ~1 \u0e40\u0e14\u0e37\u0e2d\u0e19\u0e25\u0e48\u0e32\u0e2a\u0e38\u0e14 (\u0e40\u0e01\u0e34\u0e19 4% \u0e2b\u0e23\u0e37\u0e2d\u0e40\u0e01\u0e34\u0e19 2.2 \u0e40\u0e17\u0e48\u0e32\u0e02\u0e2d\u0e07\u0e04\u0e27\u0e32\u0e21\u0e1c\u0e31\u0e19\u0e1c\u0e27\u0e19\u0e1b\u0e01\u0e15\u0e34) \u0e1e\u0e23\u0e49\u0e2d\u0e21\u0e15\u0e25\u0e32\u0e14/\u0e01\u0e25\u0e38\u0e48\u0e21\u0e27\u0e31\u0e19\u0e40\u0e14\u0e35\u0e22\u0e27\u0e01\u0e31\u0e19"""
    uniq = list(dict.fromkeys([sym, "SPY"] + ([etf] if etf else [])))
    try:
        d = yf.download(" ".join(uniq), period="6mo", interval="1d", group_by="ticker", progress=False, auto_adjust=True)
        c = d[sym]["Close"].dropna()
        spy = d["SPY"]["Close"].dropna()
        sec = d[etf]["Close"].dropna() if etf else None
    except Exception:
        return []
    if len(c) < 70:
        return []
    ret = c.pct_change().dropna() * 100
    z = ret / ret.rolling(60).std().shift(1)
    cut = c.index[-1] - pd.Timedelta(days=last_days)
    out = []
    for dt, r in ret.items():
        if dt < cut or dt == c.index[-1]:                      # \u0e27\u0e31\u0e19\u0e25\u0e48\u0e32\u0e2a\u0e38\u0e14\u0e21\u0e35\u0e01\u0e32\u0e23\u0e4c\u0e14\u0e40\u0e25\u0e48\u0e32\u0e40\u0e23\u0e37\u0e48\u0e2d\u0e07\u0e2d\u0e22\u0e39\u0e48\u0e41\u0e25\u0e49\u0e27
            continue
        zz = z.get(dt)
        if abs(r) >= 4 or (zz is not None and _ok(float(zz)) and abs(float(zz)) >= 2.2):
            g = lambda ser: (float(ser.pct_change().loc[dt]) * 100) if ser is not None and dt in ser.index and ser.index.get_loc(dt) > 0 else None
            out.append({"date": dt.date(), "chg": float(r), "px": float(c.loc[dt]), "spy": g(spy), "sec": g(sec) if sec is not None else None,
                        "etf": etf, "beta": None, "z": float(zz) if zz is not None and _ok(float(zz)) else None})
    out.sort(key=lambda x: -abs(x["z"] if x["z"] is not None else x["chg"] / 3))
    return sorted(out[:4], key=lambda x: x["date"], reverse=True)


@st.cache_data(ttl=1800, show_spinner=False)
def _news_window(sym, etf, sector, date_iso, mkt_big):
    """\u0e02\u0e48\u0e32\u0e27\u0e0a\u0e48\u0e27\u0e07\u0e23\u0e2d\u0e1a\u0e27\u0e31\u0e19\u0e19\u0e31\u0e49\u0e19 (\u0e27\u0e31\u0e19\u0e01\u0e48\u0e2d\u0e19\u0e2b\u0e19\u0e49\u0e32 \u0e16\u0e36\u0e07 1 \u0e27\u0e31\u0e19\u0e2b\u0e25\u0e31\u0e07) \u0e02\u0e2d\u0e07\u0e2b\u0e38\u0e49\u0e19 + \u0e01\u0e25\u0e38\u0e48\u0e21 + \u0e15\u0e25\u0e32\u0e14 \u00b7 \u0e41\u0e1b\u0e25\u0e2b\u0e31\u0e27\u0e02\u0e49\u0e2d\u0e40\u0e1b\u0e47\u0e19\u0e44\u0e17\u0e22\u0e1f\u0e23\u0e35"""
    try:
        import news_radar
        import news_feed
    except Exception:
        return []
    d0 = _dt.date.fromisoformat(date_iso)
    rng = "after:%s before:%s" % (d0.isoformat(), (d0 + _dt.timedelta(days=2)).isoformat())     # \u0e27\u0e31\u0e19\u0e19\u0e31\u0e49\u0e19 + \u0e27\u0e31\u0e19\u0e16\u0e31\u0e14\u0e44\u0e1b (\u0e02\u0e48\u0e32\u0e27\u0e2b\u0e25\u0e31\u0e07\u0e15\u0e25\u0e32\u0e14\u0e1b\u0e34\u0e14\u0e2a\u0e2b\u0e23\u0e31\u0e10)
    qs = [("\u0e2b\u0e38\u0e49\u0e19", "%s stock %s" % (sym, rng))]
    if etf == "SOXX":
        qs.append(("\u0e01\u0e25\u0e38\u0e48\u0e21", "semiconductor stocks %s" % rng))
    elif sector:
        qs.append(("\u0e01\u0e25\u0e38\u0e48\u0e21", "%s stocks %s" % (sector, rng)))
    if mkt_big:
        qs.append(("\u0e15\u0e25\u0e32\u0e14", "stock market %s" % rng))
    rows, seen = [], set()
    for tag, q in qs:
        try:
            got = news_radar.fetch_google_news(q, max_items=8) or []
        except Exception:
            got = []
        for n in got:
            t, src = news_feed._clean_title(n.get("title"), n.get("source"))
            k = news_feed._norm(t)
            if not k or k in seen:
                continue
            seen.add(k)
            rows.append({"tag": tag, "title_en": t, "link": n.get("link", ""), "source": src})
    rows = rows[:9]
    for r in rows:
        r["th"] = r["title_en"]
    return rows


_TR = {}
_TR_STATE = {"fail": 0, "until": 0.0}
_TH_RX = re.compile("[\u0e00-\u0e7f]")


def _tr_one(text):
    """\u0e41\u0e1b\u0e25\u0e2d\u0e31\u0e07\u0e01\u0e24\u0e29\u2192\u0e44\u0e17\u0e22\u0e1f\u0e23\u0e35 1 \u0e2b\u0e31\u0e27\u0e02\u0e49\u0e2d \u00b7 \u0e25\u0e2d\u0e07\u0e0b\u0e49\u0e33\u0e1e\u0e23\u0e49\u0e2d\u0e21\u0e2b\u0e19\u0e48\u0e27\u0e07\u0e40\u0e27\u0e25\u0e32 \u0e41\u0e25\u0e49\u0e27\u0e2a\u0e25\u0e31\u0e1a\u0e44\u0e1b\u0e43\u0e0a\u0e49\u0e1b\u0e25\u0e32\u0e22\u0e17\u0e32\u0e07\u0e2a\u0e33\u0e23\u0e2d\u0e07 \u00b7 \u0e08\u0e33\u0e1c\u0e25\u0e17\u0e35\u0e48\u0e2a\u0e33\u0e40\u0e23\u0e47\u0e08\u0e44\u0e27\u0e49 (\u0e1c\u0e25\u0e25\u0e49\u0e21\u0e40\u0e2b\u0e25\u0e27\u0e44\u0e21\u0e48\u0e16\u0e39\u0e01\u0e08\u0e33)"""
    if not text or _TH_RX.search(text):
        return text
    if text in _TR:
        return _TR[text]
    import time as _tm
    import urllib.request as _ur
    if _tm.time() < _TR_STATE["until"]:                     # \u0e15\u0e31\u0e27\u0e41\u0e1b\u0e25\u0e16\u0e39\u0e01\u0e1a\u0e25\u0e47\u0e2d\u0e01\u0e2d\u0e22\u0e39\u0e48\u0e0a\u0e31\u0e48\u0e27\u0e04\u0e23\u0e32\u0e27: \u0e44\u0e21\u0e48\u0e40\u0e2a\u0e35\u0e22\u0e40\u0e27\u0e25\u0e32\u0e23\u0e2d \u0e43\u0e0a\u0e49\u0e2d\u0e31\u0e07\u0e01\u0e24\u0e29\u0e40\u0e14\u0e34\u0e21\u0e44\u0e1b\u0e01\u0e48\u0e2d\u0e19
        return ""
    for k in range(2):
        try:
            url = "https://translate.googleapis.com/translate_a/single?client=gtx&sl=en&tl=th&dt=t&q=" + _up.quote(text)
            with _ur.urlopen(_ur.Request(url, headers={"User-Agent": "Mozilla/5.0"}), timeout=5) as r:
                data = json.loads(r.read().decode("utf-8"))
            out = "".join(seg[0] for seg in data[0] if seg and seg[0]).strip()
            if out and _TH_RX.search(out):
                _TR[text] = out
                _TR_STATE["fail"] = 0
                return out
        except Exception:
            pass
        _tm.sleep(0.4)
    try:                                                    # \u0e1b\u0e25\u0e32\u0e22\u0e17\u0e32\u0e07\u0e2a\u0e33\u0e23\u0e2d\u0e07 (\u0e2b\u0e19\u0e49\u0e32\u0e40\u0e27\u0e47\u0e1a\u0e21\u0e37\u0e2d\u0e16\u0e37\u0e2d)
        url = "https://translate.google.com/m?sl=en&tl=th&q=" + _up.quote(text)
        with _ur.urlopen(_ur.Request(url, headers={"User-Agent": "Mozilla/5.0"}), timeout=8) as r:
            htm = r.read().decode("utf-8", "ignore")
        mm = re.search(r'class="result-container">(.*?)</div>', htm, re.S)
        if mm:
            out = _html.unescape(mm.group(1)).strip()
            if out and _TH_RX.search(out):
                _TR[text] = out
                return out
    except Exception:
        pass
    _TR_STATE["fail"] += 1
    if _TR_STATE["fail"] >= 3:                              # \u0e25\u0e49\u0e21\u0e40\u0e2b\u0e25\u0e27\u0e15\u0e34\u0e14\u0e01\u0e31\u0e19 3 \u0e2b\u0e31\u0e27\u0e02\u0e49\u0e2d: \u0e1e\u0e31\u0e01\u0e01\u0e32\u0e23\u0e41\u0e1b\u0e25 5 \u0e19\u0e32\u0e17\u0e35 (\u0e01\u0e31\u0e19\u0e2b\u0e19\u0e49\u0e32\u0e40\u0e27\u0e47\u0e1a\u0e04\u0e49\u0e32\u0e07\u0e23\u0e2d)
        _TR_STATE["until"] = _tm.time() + 300
        _TR_STATE["fail"] = 0
    return ""


def tr_list(titles):
    """\u0e41\u0e1b\u0e25\u0e2b\u0e25\u0e32\u0e22\u0e2b\u0e31\u0e27\u0e02\u0e49\u0e2d (\u0e02\u0e19\u0e32\u0e19\u0e41\u0e04\u0e48 3 \u0e40\u0e18\u0e23\u0e14 \u0e40\u0e1e\u0e37\u0e48\u0e2d\u0e44\u0e21\u0e48\u0e43\u0e2b\u0e49\u0e16\u0e39\u0e01\u0e08\u0e33\u0e01\u0e31\u0e14\u0e01\u0e32\u0e23\u0e40\u0e23\u0e35\u0e22\u0e01) \u00b7 \u0e17\u0e35\u0e48\u0e41\u0e1b\u0e25\u0e44\u0e21\u0e48\u0e44\u0e14\u0e49\u0e04\u0e37\u0e19 "" """
    from concurrent.futures import ThreadPoolExecutor
    titles = list(titles)
    if not titles:
        return []
    with ThreadPoolExecutor(max_workers=3) as ex:
        return list(ex.map(_tr_one, titles))


def _fill_th(rows):
    """\u0e40\u0e15\u0e34\u0e21\u0e04\u0e33\u0e41\u0e1b\u0e25\u0e44\u0e17\u0e22\u0e43\u0e2b\u0e49\u0e2b\u0e31\u0e27\u0e02\u0e49\u0e2d\u0e02\u0e48\u0e32\u0e27\u0e17\u0e35\u0e48\u0e22\u0e31\u0e07\u0e40\u0e1b\u0e47\u0e19\u0e2d\u0e31\u0e07\u0e01\u0e24\u0e29 (\u0e40\u0e23\u0e35\u0e22\u0e01\u0e2b\u0e25\u0e31\u0e07\u0e14\u0e36\u0e07\u0e08\u0e32\u0e01\u0e41\u0e04\u0e0a \u0e40\u0e1e\u0e37\u0e48\u0e2d\u0e44\u0e21\u0e48\u0e43\u0e2b\u0e49\u0e1c\u0e25\u0e41\u0e1b\u0e25\u0e25\u0e49\u0e21\u0e40\u0e2b\u0e25\u0e27\u0e16\u0e39\u0e01\u0e41\u0e04\u0e0a\u0e44\u0e27\u0e49)"""
    need = [r for r in rows if not _TH_RX.search(r.get("th") or "")]
    if not need:
        return rows
    th = tr_list([r.get("title_en") or r.get("title") or "" for r in need])
    for r, t in zip(need, th):
        if t:
            r["th"] = t
    return rows



def _gnews_url(q):
    return "https://news.google.com/search?q=%s&hl=en-US&gl=US&ceid=US:en" % _up.quote(q)


def _day_links(sym, d0):
    rng = "after:%s before:%s" % ((d0 - _dt.timedelta(days=1)).isoformat(), (d0 + _dt.timedelta(days=2)).isoformat())
    return _gnews_url("%s stock %s" % (sym, rng)), _gnews_url("stock market %s" % rng)


def free_prompt(sym, name, mv, evs, flows=None):
    """\u0e04\u0e33\u0e2a\u0e31\u0e48\u0e07\u0e2a\u0e33\u0e40\u0e23\u0e47\u0e08\u0e23\u0e39\u0e1b\u0e43\u0e2b\u0e49\u0e04\u0e31\u0e14\u0e25\u0e2d\u0e01\u0e44\u0e1b\u0e27\u0e32\u0e07\u0e43\u0e19\u0e41\u0e0a\u0e17 AI \u0e17\u0e35\u0e48\u0e04\u0e49\u0e19\u0e40\u0e27\u0e47\u0e1a\u0e44\u0e14\u0e49 (\u0e1f\u0e23\u0e35) \u0e41\u0e17\u0e19\u0e1b\u0e38\u0e48\u0e21 AI \u0e43\u0e19\u0e40\u0e27\u0e47\u0e1a \u00b7 \u0e43\u0e2a\u0e48\u0e15\u0e31\u0e27\u0e40\u0e25\u0e02\u0e17\u0e35\u0e48\u0e23\u0e30\u0e1a\u0e1a\u0e04\u0e33\u0e19\u0e27\u0e13\u0e44\u0e27\u0e49\u0e41\u0e25\u0e49\u0e27\u0e43\u0e2b\u0e49\u0e04\u0e23\u0e1a"""
    f = lambda v: "\u0e44\u0e21\u0e48\u0e21\u0e35\u0e02\u0e49\u0e2d\u0e21\u0e39\u0e25" if v is None else "%+.2f%%" % v
    L = ["\u0e0a\u0e48\u0e27\u0e22\u0e04\u0e49\u0e19\u0e02\u0e48\u0e32\u0e27\u0e1a\u0e19\u0e40\u0e27\u0e47\u0e1a \u0e41\u0e25\u0e49\u0e27\u0e2d\u0e18\u0e34\u0e1a\u0e32\u0e22\u0e40\u0e1b\u0e47\u0e19\u0e20\u0e32\u0e29\u0e32\u0e44\u0e17\u0e22\u0e07\u0e48\u0e32\u0e22\u0e46 \u0e27\u0e48\u0e32\u0e40\u0e01\u0e34\u0e14\u0e2d\u0e30\u0e44\u0e23\u0e02\u0e36\u0e49\u0e19\u0e01\u0e31\u0e1a\u0e2b\u0e38\u0e49\u0e19 %s (%s)" % (sym, name), "",
         "\u0e02\u0e49\u0e2d\u0e21\u0e39\u0e25\u0e17\u0e35\u0e48\u0e23\u0e30\u0e1a\u0e1a\u0e04\u0e33\u0e19\u0e27\u0e13\u0e44\u0e27\u0e49\u0e41\u0e25\u0e49\u0e27 (\u0e43\u0e0a\u0e49\u0e40\u0e1b\u0e47\u0e19\u0e2b\u0e25\u0e31\u0e01\u0e10\u0e32\u0e19 \u0e2b\u0e49\u0e32\u0e21\u0e40\u0e1b\u0e25\u0e35\u0e48\u0e22\u0e19\u0e15\u0e31\u0e27\u0e40\u0e25\u0e02):",
         "- \u0e27\u0e31\u0e19\u0e25\u0e48\u0e32\u0e2a\u0e38\u0e14 %s (\u0e40\u0e27\u0e25\u0e32\u0e2a\u0e2b\u0e23\u0e31\u0e10): \u0e1b\u0e34\u0e14 %s \u0e14\u0e2d\u0e25\u0e25\u0e32\u0e23\u0e4c \u0e40\u0e1b\u0e25\u0e35\u0e48\u0e22\u0e19 %s \u00b7 \u0e15\u0e25\u0e32\u0e14 SPY %s \u00b7 Nasdaq-100 %s \u00b7 \u0e01\u0e25\u0e38\u0e48\u0e21 %s %s" % (
             mv["date"], format(mv["px"], ",.2f"), f(mv["chg"]), f(mv.get("spy")), f(mv.get("qqq")), mv.get("etf") or "-", f(mv.get("sec")))]
    if flows:
        L.append("- \u0e40\u0e07\u0e34\u0e19\u0e44\u0e2b\u0e25: VIX %s \u00b7 \u0e1e\u0e31\u0e19\u0e18\u0e1a\u0e31\u0e15\u0e23 TLT %s \u00b7 \u0e17\u0e2d\u0e07 GLD %s \u00b7 \u0e14\u0e2d\u0e25\u0e25\u0e32\u0e23\u0e4c UUP %s" % tuple(
            f((flows.get(k) or {}).get("chg")) for k in ("^VIX", "TLT", "GLD", "UUP")))
    if evs:
        L.append("- \u0e27\u0e31\u0e19\u0e17\u0e35\u0e48\u0e2b\u0e38\u0e49\u0e19\u0e02\u0e22\u0e31\u0e1a\u0e41\u0e23\u0e07\u0e43\u0e19 1 \u0e40\u0e14\u0e37\u0e2d\u0e19\u0e25\u0e48\u0e32\u0e2a\u0e38\u0e14:")
        for e in evs:
            L.append("  \u2022 %s: %s" % (e["date"], f(e["chg"])))
    L += ["", "\u0e43\u0e2b\u0e49\u0e15\u0e2d\u0e1a\u0e15\u0e32\u0e21\u0e2b\u0e31\u0e27\u0e02\u0e49\u0e2d\u0e19\u0e35\u0e49:",
          "1) \u0e27\u0e31\u0e19\u0e25\u0e48\u0e32\u0e2a\u0e38\u0e14\u0e40\u0e01\u0e34\u0e14\u0e2d\u0e30\u0e44\u0e23\u0e02\u0e36\u0e49\u0e19 (\u0e40\u0e2b\u0e15\u0e38\u0e01\u0e32\u0e23\u0e13\u0e4c\u0e43\u0e19\u0e15\u0e25\u0e32\u0e14\u0e41\u0e25\u0e30\u0e02\u0e48\u0e32\u0e27\u0e02\u0e2d\u0e07\u0e1a\u0e23\u0e34\u0e29\u0e31\u0e17)",
          "2) \u0e44\u0e17\u0e21\u0e4c\u0e44\u0e25\u0e19\u0e4c\u0e02\u0e2d\u0e07\u0e41\u0e15\u0e48\u0e25\u0e30\u0e27\u0e31\u0e19\u0e17\u0e35\u0e48\u0e02\u0e22\u0e31\u0e1a\u0e41\u0e23\u0e07: \u0e40\u0e2b\u0e15\u0e38\u0e01\u0e32\u0e23\u0e13\u0e4c\u0e43\u0e2b\u0e0d\u0e48\u0e2d\u0e30\u0e44\u0e23 (\u0e01\u0e32\u0e23\u0e40\u0e21\u0e37\u0e2d\u0e07/\u0e19\u0e42\u0e22\u0e1a\u0e32\u0e22/\u0e40\u0e28\u0e23\u0e29\u0e10\u0e01\u0e34\u0e08\u0e21\u0e2b\u0e20\u0e32\u0e04/\u0e02\u0e48\u0e32\u0e27\u0e2d\u0e38\u0e15\u0e2a\u0e32\u0e2b\u0e01\u0e23\u0e23\u0e21/\u0e02\u0e48\u0e32\u0e27\u0e1a\u0e23\u0e34\u0e29\u0e31\u0e17) \u0e17\u0e35\u0e48\u0e01\u0e23\u0e30\u0e17\u0e1a\u0e08\u0e23\u0e34\u0e07",
          "3) \u0e40\u0e07\u0e34\u0e19\u0e01\u0e33\u0e25\u0e31\u0e07\u0e17\u0e33\u0e2d\u0e30\u0e44\u0e23: \u0e15\u0e37\u0e48\u0e19\u0e15\u0e23\u0e30\u0e2b\u0e19\u0e01\u0e02\u0e32\u0e22 \u0e25\u0e49\u0e32\u0e07\u0e01\u0e33\u0e44\u0e23 \u0e2b\u0e23\u0e37\u0e2d\u0e22\u0e49\u0e32\u0e22\u0e44\u0e1b\u0e1e\u0e31\u0e19\u0e18\u0e1a\u0e31\u0e15\u0e23 \u0e17\u0e2d\u0e07 \u0e40\u0e07\u0e34\u0e19\u0e2a\u0e14 (\u0e16\u0e49\u0e32\u0e40\u0e14\u0e32 \u0e43\u0e2b\u0e49\u0e1a\u0e2d\u0e01\u0e27\u0e48\u0e32\u0e40\u0e1b\u0e47\u0e19\u0e02\u0e49\u0e2d\u0e2a\u0e31\u0e19\u0e19\u0e34\u0e29\u0e10\u0e32\u0e19)",
          "4) \u0e2a\u0e34\u0e48\u0e07\u0e17\u0e35\u0e48\u0e04\u0e27\u0e23\u0e08\u0e31\u0e1a\u0e15\u0e32\u0e43\u0e19\u0e44\u0e21\u0e48\u0e01\u0e35\u0e48\u0e27\u0e31\u0e19-\u0e2a\u0e31\u0e1b\u0e14\u0e32\u0e2b\u0e4c\u0e02\u0e49\u0e32\u0e07\u0e2b\u0e19\u0e49\u0e32", "",
          "\u0e01\u0e15\u0e34\u0e01\u0e32: \u0e43\u0e0a\u0e49\u0e40\u0e09\u0e1e\u0e32\u0e30\u0e02\u0e48\u0e32\u0e27\u0e17\u0e35\u0e48\u0e04\u0e49\u0e19\u0e40\u0e08\u0e2d\u0e41\u0e25\u0e30\u0e15\u0e31\u0e27\u0e40\u0e25\u0e02\u0e14\u0e49\u0e32\u0e19\u0e1a\u0e19 \u0e2b\u0e49\u0e32\u0e21\u0e41\u0e15\u0e48\u0e07\u0e40\u0e2b\u0e15\u0e38\u0e01\u0e32\u0e23\u0e13\u0e4c/\u0e15\u0e31\u0e27\u0e40\u0e25\u0e02 \u00b7 \u0e16\u0e49\u0e32\u0e2b\u0e32\u0e2a\u0e32\u0e40\u0e2b\u0e15\u0e38\u0e0a\u0e31\u0e14\u0e46 \u0e44\u0e21\u0e48\u0e40\u0e08\u0e2d\u0e43\u0e2b\u0e49\u0e1a\u0e2d\u0e01\u0e15\u0e23\u0e07\u0e46 \u00b7 \u0e44\u0e21\u0e48\u0e15\u0e49\u0e2d\u0e07\u0e41\u0e19\u0e30\u0e19\u0e33\u0e0b\u0e37\u0e49\u0e2d\u0e02\u0e32\u0e22\u0e2b\u0e23\u0e37\u0e2d\u0e17\u0e33\u0e19\u0e32\u0e22\u0e23\u0e32\u0e04\u0e32 \u00b7 \u0e44\u0e21\u0e48\u0e40\u0e01\u0e34\u0e19 400 \u0e04\u0e33 \u00b7 \u0e41\u0e19\u0e1a\u0e25\u0e34\u0e07\u0e01\u0e4c\u0e41\u0e2b\u0e25\u0e48\u0e07\u0e02\u0e48\u0e32\u0e27"]
    return "\n".join(L).replace("$", "")


_DOWN_W = re.compile(r"\b(fall|falls|fell|falling|drop|drops|dropped|plunge|plunges|plunged|slid|slide|slides|sink|sinks|sank|tumble|tumbles|sell-?off|slump|slumps|lose|loses|lost|dive|dives|crash|slash|cut|cuts|down|lower|worst)\b", re.I)
_UP_W = re.compile(r"\b(jump|jumps|jumped|surge|surges|surged|soar|soars|soared|rally|rallies|rise|rises|rose|gain|gains|gained|climb|climbs|pop|pops|rebound|rebounds|bounce|bounces|record|beat|beats|up|higher|best)\b", re.I)


def _rank_by_direction(rows, chg):
    """\u0e40\u0e23\u0e35\u0e22\u0e07\u0e2b\u0e31\u0e27\u0e02\u0e49\u0e2d\u0e02\u0e48\u0e32\u0e27\u0e43\u0e2b\u0e49\u0e15\u0e23\u0e07\u0e17\u0e34\u0e28\u0e01\u0e31\u0e1a\u0e01\u0e32\u0e23\u0e02\u0e22\u0e31\u0e1a \u00b7 \u0e15\u0e31\u0e14\u0e02\u0e48\u0e32\u0e27\u0e17\u0e35\u0e48\u0e17\u0e34\u0e28\u0e15\u0e23\u0e07\u0e02\u0e49\u0e32\u0e21\u0e0a\u0e31\u0e14\u0e40\u0e08\u0e19 (\u0e40\u0e0a\u0e48\u0e19\u0e27\u0e31\u0e19\u0e17\u0e35\u0e48\u0e2b\u0e38\u0e49\u0e19\u0e02\u0e36\u0e49\u0e19 \u0e41\u0e15\u0e48\u0e2b\u0e31\u0e27\u0e02\u0e49\u0e2d\u0e1a\u0e2d\u0e01\u0e27\u0e48\u0e32\u0e23\u0e48\u0e27\u0e07)"""
    same, opp = (_UP_W, _DOWN_W) if chg > 0 else (_DOWN_W, _UP_W)
    sc = []
    for r in rows:
        t = r.get("title_en") or ""
        sc.append((len(same.findall(t)) - len(opp.findall(t)) * 2, r))
    keep = [x for x in sc if x[0] >= 0] or sc
    keep.sort(key=lambda x: -x[0])
    return [r for _, r in keep]


def build_events(sym, name, info, etf):
    """\u0e40\u0e2b\u0e15\u0e38\u0e01\u0e32\u0e23\u0e13\u0e4c\u0e2a\u0e33\u0e04\u0e31\u0e0d\u0e22\u0e49\u0e2d\u0e19\u0e2b\u0e25\u0e31\u0e07: \u0e41\u0e15\u0e48\u0e25\u0e30\u0e27\u0e31\u0e19\u0e17\u0e35\u0e48\u0e02\u0e22\u0e31\u0e1a\u0e41\u0e23\u0e07 \u2192 \u0e1b\u0e23\u0e30\u0e42\u0e22\u0e04\u0e40\u0e25\u0e48\u0e32\u0e40\u0e23\u0e37\u0e48\u0e2d\u0e07 + \u0e2b\u0e31\u0e27\u0e02\u0e49\u0e2d\u0e02\u0e48\u0e32\u0e27\u0e17\u0e35\u0e48\u0e15\u0e23\u0e07\u0e01\u0e31\u0e1a\u0e27\u0e31\u0e19\u0e19\u0e31\u0e49\u0e19
    \u0e1e\u0e39\u0e14\u0e16\u0e36\u0e07 "\u0e18\u0e35\u0e21\u0e17\u0e35\u0e48\u0e2a\u0e37\u0e48\u0e2d\u0e42\u0e22\u0e07" \u0e40\u0e09\u0e1e\u0e32\u0e30\u0e40\u0e21\u0e37\u0e48\u0e2d\u0e21\u0e35\u0e2b\u0e31\u0e27\u0e02\u0e49\u0e2d\u0e02\u0e48\u0e32\u0e27\u0e02\u0e2d\u0e07\u0e27\u0e31\u0e19\u0e19\u0e31\u0e49\u0e19\u0e2a\u0e19\u0e31\u0e1a\u0e2a\u0e19\u0e38\u0e19\u0e2d\u0e22\u0e48\u0e32\u0e07\u0e19\u0e49\u0e2d\u0e22 2 \u0e02\u0e48\u0e32\u0e27 (\u0e44\u0e21\u0e48\u0e07\u0e31\u0e49\u0e19\u0e41\u0e2a\u0e14\u0e07\u0e41\u0e04\u0e48\u0e2b\u0e31\u0e27\u0e02\u0e49\u0e2d\u0e02\u0e48\u0e32\u0e27 \u0e44\u0e21\u0e48\u0e40\u0e15\u0e34\u0e21\u0e04\u0e33\u0e2d\u0e18\u0e34\u0e1a\u0e32\u0e22\u0e2a\u0e33\u0e40\u0e23\u0e47\u0e08\u0e23\u0e39\u0e1b)"""
    evs = []
    for mv in _big_days(sym, etf):
        mk = abs(mv.get("spy") or 0) >= 1.0
        rows = _rank_by_direction(_news_window(sym, etf or "", info.get("sector") or "", mv["date"].isoformat(), mk), mv["chg"])
        _fill_th(rows[:6])
        kind = why_kind(mv)
        th = [t for t in _themes_from([r.get("title_en") or "" for r in rows]) if t["key"] != "chip_sector" and len(t["idx"]) >= 2]
        sp = story_parts(sym, name, mv, kind, rows if th else [], None, use_news=bool(th))
        heads = [{"t": r.get("th") or r["title_en"], "s": r.get("source", ""), "l": r.get("link", ""), "tag": r.get("tag", "")} for r in rows[:3]]
        l1, l2 = _day_links(sym, mv["date"])
        evs.append({"date": mv["date"], "chg": mv["chg"], "sentence": sp["sentence"].strip(), "chip": sp["chip"], "heads": heads, "nrows": len(rows),
                    "l_stock": l1, "l_mkt": l2, "sym": sym, "themed": bool(th)})
    return evs


def _events_html(evs):
    if not evs:
        return '<div class="in-th-empty">1 \u0e40\u0e14\u0e37\u0e2d\u0e19\u0e17\u0e35\u0e48\u0e1c\u0e48\u0e32\u0e19\u0e21\u0e32\u0e44\u0e21\u0e48\u0e21\u0e35\u0e27\u0e31\u0e19\u0e17\u0e35\u0e48\u0e2b\u0e38\u0e49\u0e19\u0e15\u0e31\u0e27\u0e19\u0e35\u0e49\u0e02\u0e22\u0e31\u0e1a\u0e1c\u0e34\u0e14\u0e1b\u0e01\u0e15\u0e34 (\u0e40\u0e01\u0e34\u0e19 4% \u0e2b\u0e23\u0e37\u0e2d\u0e40\u0e01\u0e34\u0e19\u0e04\u0e27\u0e32\u0e21\u0e1c\u0e31\u0e19\u0e1c\u0e27\u0e19\u0e1b\u0e01\u0e15\u0e34\u0e21\u0e32\u0e01) \u2014 \u0e44\u0e21\u0e48\u0e21\u0e35\u0e40\u0e2b\u0e15\u0e38\u0e01\u0e32\u0e23\u0e13\u0e4c\u0e43\u0e2b\u0e0d\u0e48\u0e43\u0e2b\u0e49\u0e44\u0e25\u0e48\u0e22\u0e49\u0e2d\u0e19</div>'
    cards = ""
    for e in evs:
        col = _UPC if e["chg"] >= 0 else _DNC
        hl = "".join('<div class="in-ev-h"><a href="%s" target="_blank" rel="noopener">%s</a> <small>%s</small></div>' % (_e(h["l"]), _e(h["t"]), _e(h["s"])) for h in e["heads"])
        if not hl:
            hl = '<div class="in-ev-h"><small>\u0e44\u0e21\u0e48\u0e1e\u0e1a\u0e2b\u0e31\u0e27\u0e02\u0e49\u0e2d\u0e02\u0e48\u0e32\u0e27\u0e23\u0e2d\u0e1a\u0e27\u0e31\u0e19\u0e19\u0e31\u0e49\u0e19</small></div>'
        elif not e.get("themed"):
            hl = '<div class="in-ev-h"><small>\u0e44\u0e21\u0e48\u0e1e\u0e1a\u0e02\u0e48\u0e32\u0e27\u0e17\u0e35\u0e48\u0e0a\u0e35\u0e49\u0e0a\u0e31\u0e14\u0e27\u0e48\u0e32\u0e40\u0e1b\u0e47\u0e19\u0e2a\u0e32\u0e40\u0e2b\u0e15\u0e38 \u2014 \u0e01\u0e14\u0e04\u0e49\u0e19\u0e02\u0e48\u0e32\u0e27\u0e27\u0e31\u0e19\u0e19\u0e31\u0e49\u0e19\u0e40\u0e2d\u0e07\u0e14\u0e49\u0e32\u0e19\u0e25\u0e48\u0e32\u0e07\u0e40\u0e1e\u0e37\u0e48\u0e2d\u0e15\u0e23\u0e27\u0e08 (\u0e44\u0e21\u0e48\u0e41\u0e2a\u0e14\u0e07\u0e2b\u0e31\u0e27\u0e02\u0e49\u0e2d\u0e02\u0e48\u0e32\u0e27\u0e04\u0e31\u0e14\u0e21\u0e31\u0e48\u0e27\u0e46 \u0e40\u0e1e\u0e37\u0e48\u0e2d\u0e44\u0e21\u0e48\u0e43\u0e2b\u0e49\u0e40\u0e14\u0e32\u0e2a\u0e32\u0e40\u0e2b\u0e15\u0e38\u0e1c\u0e34\u0e14)</small></div>'
        cards += ('<div class="in-ev" style="--ac:%s"><div class="in-ev-top"><div class="in-ev-pct" style="color:%s!important">%s</div>'
                  '<div class="in-ev-d">%d %s</div><div class="in-st-chip" style="color:%s!important;border-color:%s">%s</div></div>'
                  '<div class="in-ev-s">%s</div>%s<div class="in-ev-h"><a href="%s" target="_blank" rel="noopener" style="color:#7fdcff">\u0e04\u0e49\u0e19\u0e02\u0e48\u0e32\u0e27 %s \u0e27\u0e31\u0e19\u0e19\u0e31\u0e49\u0e19\u0e40\u0e2d\u0e07 \u2197</a> \u00b7 <a href="%s" target="_blank" rel="noopener" style="color:#7fdcff">\u0e02\u0e48\u0e32\u0e27\u0e15\u0e25\u0e32\u0e14\u0e23\u0e27\u0e21\u0e27\u0e31\u0e19\u0e19\u0e31\u0e49\u0e19 \u2197</a></div></div>') % (
            col, col, _pct(e["chg"], 1, True), e["date"].day, _TH_MON[e["date"].month - 1], e["chip"][1], e["chip"][1], _e(e["chip"][0]), _e(e["sentence"]), hl, _e(e.get("l_stock", "#")), _e(e.get("sym", "")), _e(e.get("l_mkt", "#")))
    return ('<div class="in-sec">\u0e40\u0e2b\u0e15\u0e38\u0e01\u0e32\u0e23\u0e13\u0e4c\u0e2a\u0e33\u0e04\u0e31\u0e0d\u0e17\u0e35\u0e48\u0e1c\u0e48\u0e32\u0e19\u0e21\u0e32 (\u0e27\u0e31\u0e19\u0e17\u0e35\u0e48\u0e2b\u0e38\u0e49\u0e19\u0e02\u0e22\u0e31\u0e1a\u0e1c\u0e34\u0e14\u0e1b\u0e01\u0e15\u0e34\u0e43\u0e19 1 \u0e40\u0e14\u0e37\u0e2d\u0e19\u0e25\u0e48\u0e32\u0e2a\u0e38\u0e14)</div><div class="in-evs">%s</div>'
            '<div class="in-foot">\u0e04\u0e31\u0e14\u0e08\u0e32\u0e01\u0e27\u0e31\u0e19\u0e17\u0e35\u0e48\u0e23\u0e32\u0e04\u0e32\u0e02\u0e22\u0e31\u0e1a\u0e41\u0e23\u0e07\u0e1c\u0e34\u0e14\u0e1b\u0e01\u0e15\u0e34 \u0e41\u0e25\u0e49\u0e27\u0e14\u0e36\u0e07\u0e2b\u0e31\u0e27\u0e02\u0e49\u0e2d\u0e02\u0e48\u0e32\u0e27\u0e23\u0e2d\u0e1a\u0e27\u0e31\u0e19\u0e19\u0e31\u0e49\u0e19\u0e21\u0e32\u0e1b\u0e23\u0e30\u0e01\u0e2d\u0e1a \u0e44\u0e21\u0e48\u0e44\u0e14\u0e49\u0e22\u0e37\u0e19\u0e22\u0e31\u0e19\u0e2a\u0e32\u0e40\u0e2b\u0e15\u0e38 \u00b7 \u0e40\u0e2b\u0e15\u0e38\u0e01\u0e32\u0e23\u0e13\u0e4c\u0e43\u0e2b\u0e0d\u0e48\u0e23\u0e30\u0e14\u0e31\u0e1a\u0e1b\u0e23\u0e30\u0e40\u0e17\u0e28 (\u0e40\u0e0a\u0e48\u0e19 \u0e40\u0e25\u0e37\u0e2d\u0e01\u0e15\u0e31\u0e49\u0e07) \u0e08\u0e30\u0e40\u0e2b\u0e47\u0e19\u0e44\u0e14\u0e49\u0e08\u0e32\u0e01\u0e02\u0e48\u0e32\u0e27\u0e15\u0e25\u0e32\u0e14\u0e23\u0e27\u0e21\u0e43\u0e19\u0e27\u0e31\u0e19\u0e40\u0e14\u0e35\u0e22\u0e27\u0e01\u0e31\u0e19 \u0e2b\u0e23\u0e37\u0e2d\u0e01\u0e14\u0e43\u0e2b\u0e49 AI \u0e04\u0e49\u0e19\u0e22\u0e49\u0e2d\u0e19\u0e2b\u0e25\u0e31\u0e07\u0e14\u0e49\u0e32\u0e19\u0e25\u0e48\u0e32\u0e07</div>') % cards


