# \u0e40\u0e04\u0e23\u0e37\u0e48\u0e2d\u0e07\u0e04\u0e33\u0e19\u0e27\u0e13\u0e04\u0e27\u0e32\u0e21\u0e01\u0e23\u0e30\u0e08\u0e38\u0e01\u0e15\u0e31\u0e27 (\u0e43\u0e2a\u0e48\u0e02\u0e49\u0e2d\u0e21\u0e39\u0e25\u0e01\u0e25\u0e38\u0e48\u0e21\u0e18\u0e38\u0e23\u0e01\u0e34\u0e08\u0e40\u0e2d\u0e07\u0e08\u0e32\u0e01\u0e41\u0e16\u0e25\u0e07\u0e07\u0e1a)
# ---------------------------------------------------------------
def parse_segments(text):
    """\u0e1a\u0e23\u0e23\u0e17\u0e31\u0e14\u0e25\u0e30\u0e01\u0e25\u0e38\u0e48\u0e21: \u0e0a\u0e37\u0e48\u0e2d, \u0e15\u0e2d\u0e19\u0e19\u0e35\u0e49, \u0e0a\u0e48\u0e27\u0e07\u0e40\u0e17\u0e35\u0e22\u0e1a \u00b7 \u0e43\u0e2a\u0e48\u0e15\u0e31\u0e27\u0e40\u0e25\u0e02\u0e21\u0e35\u0e04\u0e2d\u0e21\u0e21\u0e32\u0e04\u0e31\u0e48\u0e19\u0e2b\u0e25\u0e31\u0e01\u0e1e\u0e31\u0e19\u0e44\u0e14\u0e49 (8,500)"""
    import re as _re
    rows = []
    for line in str(text or "").replace("\t", ",").splitlines():
        line = _re.sub(r"(?<=\d),(?=\d{3}(?!\d))", "", line)          # \u0e15\u0e31\u0e14\u0e04\u0e2d\u0e21\u0e21\u0e32\u0e2b\u0e25\u0e31\u0e01\u0e1e\u0e31\u0e19\u0e01\u0e48\u0e2d\u0e19\u0e41\u0e22\u0e01\u0e0a\u0e48\u0e2d\u0e07
        parts = [p.strip() for p in line.split(",")]
        if len(parts) >= 3:
            try:
                rows.append((parts[0], float(parts[-2]), float(parts[-1])))
            except Exception:
                continue
    return rows


def concentration(rows):
    """rows: [(\u0e0a\u0e37\u0e48\u0e2d, \u0e23\u0e32\u0e22\u0e44\u0e14\u0e49\u0e15\u0e2d\u0e19\u0e19\u0e35\u0e49, \u0e23\u0e32\u0e22\u0e44\u0e14\u0e49\u0e0a\u0e48\u0e27\u0e07\u0e40\u0e17\u0e35\u0e22\u0e1a)] \u2192 \u0e2a\u0e48\u0e27\u0e19\u0e41\u0e1a\u0e48\u0e07\u0e23\u0e32\u0e22\u0e44\u0e14\u0e49 + \u0e2a\u0e48\u0e27\u0e19\u0e41\u0e1a\u0e48\u0e07\u0e01\u0e32\u0e23\u0e40\u0e15\u0e34\u0e1a\u0e42\u0e15\u0e02\u0e2d\u0e07\u0e41\u0e15\u0e48\u0e25\u0e30\u0e01\u0e25\u0e38\u0e48\u0e21"""
    tot0, totb = sum(r[1] for r in rows), sum(r[2] for r in rows)
    dt = tot0 - totb
    out = []
    for name, v, b in rows:
        out.append({"name": name, "now": v, "base": b, "share": v / tot0 * 100 if tot0 else None,
                    "share_base": b / totb * 100 if totb else None, "growth": (v / b - 1) * 100 if b else None,
                    "contrib": (v - b) / dt * 100 if dt else None})
    return out, tot0, totb, dt


