def _hl(t):
    """escape \u0e41\u0e25\u0e49\u0e27\u0e40\u0e19\u0e49\u0e19\u0e15\u0e31\u0e27\u0e40\u0e25\u0e02/\u0e40\u0e1b\u0e2d\u0e23\u0e4c\u0e40\u0e0b\u0e47\u0e19\u0e15\u0e4c\u0e43\u0e2b\u0e49\u0e40\u0e14\u0e48\u0e19 (\u0e2d\u0e48\u0e32\u0e19\u0e1c\u0e48\u0e32\u0e19\u0e15\u0e32\u0e01\u0e47\u0e40\u0e2b\u0e47\u0e19\u0e15\u0e31\u0e27\u0e40\u0e25\u0e02\u0e2a\u0e33\u0e04\u0e31\u0e0d)"""
    return _HLRE.sub(lambda m: '<b class="n">%s</b>' % m.group(1), _e(t))


_SS_ICON = {"\u0e15\u0e2d\u0e19\u0e19\u0e35\u0e49\u0e40\u0e1b\u0e47\u0e19\u0e22\u0e31\u0e07\u0e44\u0e07": "\U0001f4cd", "\u0e40\u0e2b\u0e15\u0e38\u0e01\u0e32\u0e23\u0e13\u0e4c\u0e17\u0e35\u0e48\u0e1c\u0e48\u0e32\u0e19\u0e21\u0e32": "\U0001f552", "\u0e41\u0e19\u0e27\u0e42\u0e19\u0e49\u0e21\u0e08\u0e32\u0e01\u0e15\u0e31\u0e27\u0e40\u0e25\u0e02": "\U0001f52d", "\u0e08\u0e38\u0e14\u0e41\u0e02\u0e47\u0e07": "\U0001f4aa",
            "\u0e15\u0e49\u0e2d\u0e07\u0e23\u0e30\u0e27\u0e31\u0e07": "\u26a0\ufe0f", "\u0e42\u0e0b\u0e19\u0e23\u0e32\u0e04\u0e32\u0e15\u0e2d\u0e19\u0e19\u0e35\u0e49": "\U0001f3af", "\u0e08\u0e38\u0e14\u0e40\u0e14\u0e48\u0e19 / \u0e08\u0e38\u0e14\u0e17\u0e35\u0e48\u0e04\u0e27\u0e23\u0e40\u0e0a\u0e47\u0e01": "\U0001f50e", "\u0e04\u0e27\u0e32\u0e21\u0e19\u0e48\u0e32\u0e40\u0e0a\u0e37\u0e48\u0e2d\u0e16\u0e37\u0e2d\u0e02\u0e2d\u0e07\u0e02\u0e49\u0e2d\u0e21\u0e39\u0e25": "\U0001f6e1\ufe0f",
            "\u0e15\u0e25\u0e32\u0e14\u0e23\u0e27\u0e21\u0e15\u0e2d\u0e19\u0e19\u0e35\u0e49": "\U0001f310"}


def _sec_html(rows, title="\u0e2a\u0e23\u0e38\u0e1b\u0e2b\u0e31\u0e27\u0e02\u0e49\u0e2d\u0e19\u0e35\u0e49\u0e41\u0e1a\u0e1a\u0e40\u0e02\u0e49\u0e32\u0e43\u0e08\u0e07\u0e48\u0e32\u0e22"):
    """\u0e01\u0e25\u0e48\u0e2d\u0e07\u0e2a\u0e23\u0e38\u0e1b\u0e2a\u0e31\u0e49\u0e19\u0e46 \u0e02\u0e2d\u0e07\u0e41\u0e15\u0e48\u0e25\u0e30\u0e2a\u0e48\u0e27\u0e19: rows = [(\u0e1b\u0e49\u0e32\u0e22, \u0e02\u0e49\u0e2d\u0e04\u0e27\u0e32\u0e21)] \u2014 \u0e15\u0e2d\u0e19\u0e19\u0e35\u0e49\u0e40\u0e1b\u0e47\u0e19\u0e22\u0e31\u0e07\u0e44\u0e07 \u00b7 \u0e41\u0e1b\u0e25\u0e27\u0e48\u0e32\u0e2d\u0e30\u0e44\u0e23 \u00b7 \u0e41\u0e19\u0e27\u0e42\u0e19\u0e49\u0e21\u0e08\u0e32\u0e01\u0e15\u0e31\u0e27\u0e40\u0e25\u0e02"""
    if not rows:
        return ""
    body = ""
    for a_, b_ in rows:
        if not b_:
            continue
        ic = next((v for k, v in _SS_ICON.items() if a_.startswith(k)), "\u2022")
        body += '<div class="in-ss-r"><div class="in-ss-k"><span>%s</span>%s</div><div class="in-ss-v">%s</div></div>' % (ic, _e(a_), _hl(b_))
    return '<div class="in-ss"><div class="in-ss-h"><i></i>\U0001f5d2\ufe0f %s</div>%s</div>' % (_e(title), body)


def sum_today(sym, mv):
    """\u0e2a\u0e48\u0e27\u0e19 2: \u0e27\u0e31\u0e19\u0e19\u0e35\u0e49 + \u0e40\u0e2b\u0e15\u0e38\u0e01\u0e32\u0e23\u0e13\u0e4c\u0e17\u0e35\u0e48\u0e1c\u0e48\u0e32\u0e19\u0e21\u0e32"""
    if not mv:
        return []
    kind = why_kind(mv)
    grp = _GRP_TH.get(mv.get("etf"), mv.get("etf") or "\u0e01\u0e25\u0e38\u0e48\u0e21")
    now = "\u0e27\u0e31\u0e19\u0e19\u0e35\u0e49 %s %s %.2f%%" % (sym, "\u0e02\u0e36\u0e49\u0e19" if mv["chg"] >= 0 else "\u0e25\u0e07", abs(mv["chg"]))
    refs = []
    if _ok(mv.get("spy")):
        refs.append("\u0e15\u0e25\u0e32\u0e14 S&P %s" % _pct(mv["spy"], 1, True))
    if _ok(mv.get("sec")) and mv.get("etf"):
        refs.append("\u0e01\u0e25\u0e38\u0e48\u0e21 %s %s" % (grp, _pct(mv["sec"], 1, True)))
    if refs:
        now += " (" + " \u00b7 ".join(refs) + ")"
    mean = {"normal": "\u0e02\u0e22\u0e31\u0e1a\u0e43\u0e19\u0e23\u0e30\u0e14\u0e31\u0e1a\u0e1b\u0e01\u0e15\u0e34 \u0e44\u0e21\u0e48\u0e21\u0e35\u0e2d\u0e30\u0e44\u0e23\u0e1c\u0e34\u0e14\u0e1b\u0e01\u0e15\u0e34\u0e17\u0e35\u0e48\u0e15\u0e49\u0e2d\u0e07\u0e2b\u0e32\u0e2a\u0e32\u0e40\u0e2b\u0e15\u0e38",
            "sector": "\u0e1e\u0e39\u0e14\u0e07\u0e48\u0e32\u0e22\u0e46 \u0e04\u0e37\u0e2d\u0e2a\u0e48\u0e27\u0e19\u0e43\u0e2b\u0e0d\u0e48\u0e02\u0e22\u0e31\u0e1a\u0e15\u0e32\u0e21\u0e01\u0e25\u0e38\u0e48\u0e21 %s \u0e44\u0e21\u0e48\u0e43\u0e0a\u0e48\u0e40\u0e23\u0e37\u0e48\u0e2d\u0e07\u0e40\u0e09\u0e1e\u0e32\u0e30\u0e02\u0e2d\u0e07\u0e1a\u0e23\u0e34\u0e29\u0e31\u0e17" % grp,
            "market": "\u0e1e\u0e39\u0e14\u0e07\u0e48\u0e32\u0e22\u0e46 \u0e04\u0e37\u0e2d\u0e2a\u0e48\u0e27\u0e19\u0e43\u0e2b\u0e0d\u0e48\u0e02\u0e22\u0e31\u0e1a\u0e15\u0e32\u0e21\u0e15\u0e25\u0e32\u0e14\u0e23\u0e27\u0e21 \u0e44\u0e21\u0e48\u0e43\u0e0a\u0e48\u0e40\u0e23\u0e37\u0e48\u0e2d\u0e07\u0e40\u0e09\u0e1e\u0e32\u0e30\u0e02\u0e2d\u0e07\u0e1a\u0e23\u0e34\u0e29\u0e31\u0e17",
            "sector_plus": "\u0e02\u0e22\u0e31\u0e1a\u0e15\u0e32\u0e21\u0e01\u0e25\u0e38\u0e48\u0e21\u0e1a\u0e32\u0e07\u0e2a\u0e48\u0e27\u0e19 \u0e41\u0e15\u0e48\u0e41\u0e23\u0e07\u0e01\u0e27\u0e48\u0e32\u0e01\u0e25\u0e38\u0e48\u0e21\u0e0a\u0e31\u0e14\u0e40\u0e08\u0e19 \u0e19\u0e48\u0e32\u0e08\u0e30\u0e21\u0e35\u0e40\u0e23\u0e37\u0e48\u0e2d\u0e07\u0e40\u0e09\u0e1e\u0e32\u0e30\u0e15\u0e31\u0e27\u0e23\u0e48\u0e27\u0e21\u0e14\u0e49\u0e27\u0e22",
            "market_plus": "\u0e02\u0e22\u0e31\u0e1a\u0e15\u0e32\u0e21\u0e15\u0e25\u0e32\u0e14\u0e1a\u0e32\u0e07\u0e2a\u0e48\u0e27\u0e19 \u0e41\u0e15\u0e48\u0e41\u0e23\u0e07\u0e01\u0e27\u0e48\u0e32\u0e17\u0e35\u0e48\u0e15\u0e25\u0e32\u0e14\u0e2d\u0e18\u0e34\u0e1a\u0e32\u0e22\u0e44\u0e14\u0e49 \u0e19\u0e48\u0e32\u0e08\u0e30\u0e21\u0e35\u0e40\u0e23\u0e37\u0e48\u0e2d\u0e07\u0e40\u0e09\u0e1e\u0e32\u0e30\u0e15\u0e31\u0e27\u0e23\u0e48\u0e27\u0e21\u0e14\u0e49\u0e27\u0e22",
            "own": "\u0e02\u0e22\u0e31\u0e1a\u0e41\u0e23\u0e07\u0e17\u0e31\u0e49\u0e07\u0e17\u0e35\u0e48\u0e15\u0e25\u0e32\u0e14\u0e41\u0e25\u0e30\u0e01\u0e25\u0e38\u0e48\u0e21\u0e44\u0e21\u0e48\u0e44\u0e14\u0e49\u0e02\u0e22\u0e31\u0e1a\u0e15\u0e32\u0e21 \u0e19\u0e48\u0e32\u0e08\u0e30\u0e21\u0e35\u0e40\u0e23\u0e37\u0e48\u0e2d\u0e07\u0e40\u0e09\u0e1e\u0e32\u0e30\u0e15\u0e31\u0e27 \u0e25\u0e2d\u0e07\u0e14\u0e39\u0e02\u0e48\u0e32\u0e27\u0e1b\u0e23\u0e30\u0e01\u0e2d\u0e1a"}[kind]
    rows = [("\u0e15\u0e2d\u0e19\u0e19\u0e35\u0e49\u0e40\u0e1b\u0e47\u0e19\u0e22\u0e31\u0e07\u0e44\u0e07", now + " \u2014 " + mean + ".")]
    evs = mv.get("_events")
    if evs is not None:
        if not evs:
            rows.append(("\u0e40\u0e2b\u0e15\u0e38\u0e01\u0e32\u0e23\u0e13\u0e4c\u0e17\u0e35\u0e48\u0e1c\u0e48\u0e32\u0e19\u0e21\u0e32", "\u0e22\u0e49\u0e2d\u0e19\u0e44\u0e1b 1 \u0e40\u0e14\u0e37\u0e2d\u0e19 \u0e44\u0e21\u0e48\u0e21\u0e35\u0e27\u0e31\u0e19\u0e44\u0e2b\u0e19\u0e17\u0e35\u0e48\u0e23\u0e32\u0e04\u0e32\u0e01\u0e23\u0e30\u0e0a\u0e32\u0e01\u0e41\u0e23\u0e07\u0e1c\u0e34\u0e14\u0e1b\u0e01\u0e15\u0e34 \u0e23\u0e32\u0e04\u0e32\u0e04\u0e48\u0e2d\u0e19\u0e02\u0e49\u0e32\u0e07\u0e19\u0e34\u0e48\u0e07"))
        else:
            n_g = sum(1 for e in evs if "\u0e15\u0e32\u0e21\u0e01\u0e25\u0e38\u0e48\u0e21" in (e.get("chip") or ""))
            n_m = sum(1 for e in evs if "\u0e15\u0e32\u0e21\u0e15\u0e25\u0e32\u0e14" in (e.get("chip") or ""))
            n_t = sum(1 for e in evs if e.get("themed") and e.get("head"))
            parts = []
            if n_g:
                parts.append("%d \u0e04\u0e23\u0e31\u0e49\u0e07\u0e02\u0e22\u0e31\u0e1a\u0e15\u0e32\u0e21\u0e01\u0e25\u0e38\u0e48\u0e21" % n_g)
            if n_m:
                parts.append("%d \u0e04\u0e23\u0e31\u0e49\u0e07\u0e02\u0e22\u0e31\u0e1a\u0e15\u0e32\u0e21\u0e15\u0e25\u0e32\u0e14" % n_m)
            if n_t:
                parts.append("%d \u0e04\u0e23\u0e31\u0e49\u0e07\u0e21\u0e35\u0e02\u0e48\u0e32\u0e27\u0e23\u0e2d\u0e1a\u0e27\u0e31\u0e19\u0e19\u0e31\u0e49\u0e19\u0e23\u0e2d\u0e07\u0e23\u0e31\u0e1a" % n_t)
            else:
                parts.append("\u0e44\u0e21\u0e48\u0e1e\u0e1a\u0e02\u0e48\u0e32\u0e27\u0e40\u0e09\u0e1e\u0e32\u0e30\u0e15\u0e31\u0e27\u0e17\u0e35\u0e48\u0e0a\u0e35\u0e49\u0e0a\u0e31\u0e14")
            rows.append(("\u0e40\u0e2b\u0e15\u0e38\u0e01\u0e32\u0e23\u0e13\u0e4c\u0e17\u0e35\u0e48\u0e1c\u0e48\u0e32\u0e19\u0e21\u0e32", "\u0e22\u0e49\u0e2d\u0e19\u0e44\u0e1b 1 \u0e40\u0e14\u0e37\u0e2d\u0e19 \u0e21\u0e35 %d \u0e27\u0e31\u0e19\u0e17\u0e35\u0e48\u0e23\u0e32\u0e04\u0e32\u0e01\u0e23\u0e30\u0e0a\u0e32\u0e01\u0e41\u0e23\u0e07\u0e1c\u0e34\u0e14\u0e1b\u0e01\u0e15\u0e34 \u2014 %s" % (len(evs), " \u0e41\u0e25\u0e30 ".join(parts))))
    if kind in ("sector", "sector_plus", "market", "market_plus"):
        who = "\u0e15\u0e25\u0e32\u0e14\u0e23\u0e27\u0e21" if kind.startswith("market") else "\u0e01\u0e25\u0e38\u0e48\u0e21 " + grp
        tr = "\u0e16\u0e49\u0e32%s\u0e22\u0e31\u0e07\u0e41\u0e01\u0e27\u0e48\u0e07\u0e2d\u0e22\u0e39\u0e48 \u0e23\u0e32\u0e04\u0e32\u0e15\u0e31\u0e27\u0e19\u0e35\u0e49\u0e01\u0e47\u0e21\u0e31\u0e01\u0e41\u0e01\u0e27\u0e48\u0e07\u0e15\u0e32\u0e21 \u0e40\u0e25\u0e22\u0e04\u0e27\u0e23\u0e14\u0e39\u0e17\u0e34\u0e28\u0e17\u0e32\u0e07\u0e02\u0e2d\u0e07%s\u0e04\u0e27\u0e1a\u0e04\u0e39\u0e48\u0e44\u0e1b\u0e14\u0e49\u0e27\u0e22 \u0e2d\u0e22\u0e48\u0e32\u0e2a\u0e23\u0e38\u0e1b\u0e08\u0e32\u0e01\u0e15\u0e31\u0e27\u0e1a\u0e23\u0e34\u0e29\u0e31\u0e17\u0e2d\u0e22\u0e48\u0e32\u0e07\u0e40\u0e14\u0e35\u0e22\u0e27" % (who, who)
    elif kind == "own":
        tr = "\u0e16\u0e49\u0e32\u0e02\u0e48\u0e32\u0e27\u0e2b\u0e23\u0e37\u0e2d\u0e40\u0e23\u0e37\u0e48\u0e2d\u0e07\u0e40\u0e09\u0e1e\u0e32\u0e30\u0e15\u0e31\u0e27\u0e22\u0e31\u0e07\u0e21\u0e35\u0e15\u0e48\u0e2d\u0e40\u0e19\u0e37\u0e48\u0e2d\u0e07 \u0e23\u0e32\u0e04\u0e32\u0e21\u0e31\u0e01\u0e41\u0e01\u0e27\u0e48\u0e07\u0e41\u0e23\u0e07\u0e15\u0e48\u0e2d\u0e44\u0e1b\u0e08\u0e19\u0e01\u0e27\u0e48\u0e32\u0e40\u0e23\u0e37\u0e48\u0e2d\u0e07\u0e08\u0e30\u0e0a\u0e31\u0e14\u0e40\u0e08\u0e19 \u0e25\u0e2d\u0e07\u0e14\u0e39\u0e02\u0e48\u0e32\u0e27\u0e41\u0e25\u0e30\u0e27\u0e2d\u0e25\u0e38\u0e48\u0e21\u0e40\u0e1e\u0e34\u0e48\u0e21"
    else:
        tr = "\u0e15\u0e2d\u0e19\u0e19\u0e35\u0e49\u0e22\u0e31\u0e07\u0e44\u0e21\u0e48\u0e21\u0e35\u0e41\u0e23\u0e07\u0e01\u0e14\u0e14\u0e31\u0e19\u0e1c\u0e34\u0e14\u0e1b\u0e01\u0e15\u0e34 \u0e23\u0e32\u0e04\u0e32\u0e21\u0e31\u0e01\u0e40\u0e14\u0e34\u0e19\u0e15\u0e32\u0e21\u0e40\u0e17\u0e23\u0e19\u0e14\u0e4c\u0e40\u0e14\u0e34\u0e21\u0e44\u0e1b\u0e01\u0e48\u0e2d\u0e19 \u0e08\u0e19\u0e01\u0e27\u0e48\u0e32\u0e08\u0e30\u0e21\u0e35\u0e02\u0e48\u0e32\u0e27\u0e2b\u0e23\u0e37\u0e2d\u0e07\u0e1a\u0e43\u0e2b\u0e21\u0e48"
    rows.append(("\u0e41\u0e19\u0e27\u0e42\u0e19\u0e49\u0e21\u0e08\u0e32\u0e01\u0e15\u0e31\u0e27\u0e40\u0e25\u0e02 (\u0e44\u0e21\u0e48\u0e43\u0e0a\u0e48\u0e17\u0e33\u0e19\u0e32\u0e22)", tr + "."))
    mk = (mv.get("_story") or {}).get("market")
    if mk:
        rows.append(("\u0e15\u0e25\u0e32\u0e14\u0e23\u0e27\u0e21\u0e15\u0e2d\u0e19\u0e19\u0e35\u0e49", mk))
    return rows


def sum_lenses(lenses):
    """\u0e2a\u0e48\u0e27\u0e19 3: \u0e2b\u0e25\u0e31\u0e01\u0e10\u0e32\u0e19\u0e23\u0e32\u0e22\u0e21\u0e38\u0e21 (7 \u0e21\u0e38\u0e21\u0e21\u0e2d\u0e07)"""
    used = [l for l in lenses if l["stance"] in ("good", "mid", "bad")]
    if not used:
        return []
    sh = lambda l: l["title"].split(" \u2014 ")[0]
    g = [l for l in used if l["stance"] == "good"]
    b = [l for l in used if l["stance"] == "bad"]
    m = [l for l in used if l["stance"] == "mid"]
    rows = [("\u0e15\u0e2d\u0e19\u0e19\u0e35\u0e49\u0e40\u0e1b\u0e47\u0e19\u0e22\u0e31\u0e07\u0e44\u0e07", "\u0e08\u0e32\u0e01 %d \u0e21\u0e38\u0e21\u0e17\u0e35\u0e48\u0e21\u0e35\u0e02\u0e49\u0e2d\u0e21\u0e39\u0e25 \u0e44\u0e14\u0e49\u0e2a\u0e35\u0e14\u0e35 %d \u0e21\u0e38\u0e21 \u0e01\u0e25\u0e32\u0e07\u0e46 %d \u0e21\u0e38\u0e21 \u0e41\u0e25\u0e30\u0e15\u0e49\u0e2d\u0e07\u0e23\u0e30\u0e27\u0e31\u0e07 %d \u0e21\u0e38\u0e21" % (len(used), len(g), len(m), len(b)))]
    rows.append(("\u0e08\u0e38\u0e14\u0e41\u0e02\u0e47\u0e07", " \u00b7 ".join("%s \u2014 %s" % (sh(l), l["head"]) for l in g[:3]) if g else "\u0e22\u0e31\u0e07\u0e44\u0e21\u0e48\u0e21\u0e35\u0e21\u0e38\u0e21\u0e44\u0e2b\u0e19\u0e17\u0e35\u0e48\u0e40\u0e14\u0e48\u0e19\u0e0a\u0e31\u0e14"))
    rows.append(("\u0e15\u0e49\u0e2d\u0e07\u0e23\u0e30\u0e27\u0e31\u0e07", " \u00b7 ".join("%s \u2014 %s" % (sh(l), l["head"]) for l in b[:3]) if b else "\u0e22\u0e31\u0e07\u0e44\u0e21\u0e48\u0e21\u0e35\u0e21\u0e38\u0e21\u0e17\u0e35\u0e48\u0e15\u0e31\u0e27\u0e40\u0e25\u0e02\u0e0a\u0e35\u0e49\u0e27\u0e48\u0e32\u0e23\u0e30\u0e27\u0e31\u0e07"))
    wt = [l for l in (b + m) if l.get("watch")][:2]
    if wt:
        rows.append(("\u0e41\u0e19\u0e27\u0e42\u0e19\u0e49\u0e21\u0e08\u0e32\u0e01\u0e15\u0e31\u0e27\u0e40\u0e25\u0e02 (\u0e44\u0e21\u0e48\u0e43\u0e0a\u0e48\u0e17\u0e33\u0e19\u0e32\u0e22)", "\u0e20\u0e32\u0e1e\u0e23\u0e27\u0e21\u0e08\u0e30\u0e02\u0e22\u0e31\u0e1a\u0e44\u0e1b\u0e17\u0e32\u0e07\u0e44\u0e2b\u0e19\u0e02\u0e36\u0e49\u0e19\u0e01\u0e31\u0e1a\u0e40\u0e23\u0e37\u0e48\u0e2d\u0e07\u0e40\u0e2b\u0e25\u0e48\u0e32\u0e19\u0e35\u0e49: " + " \u00b7 ".join("%s: %s" % (sh(l), l["watch"]) for l in wt)))
    else:
        fw = next((l for l in used if l["key"] == "forward" and l.get("head")), None)
        rows.append(("\u0e41\u0e19\u0e27\u0e42\u0e19\u0e49\u0e21\u0e08\u0e32\u0e01\u0e15\u0e31\u0e27\u0e40\u0e25\u0e02 (\u0e44\u0e21\u0e48\u0e43\u0e0a\u0e48\u0e17\u0e33\u0e19\u0e32\u0e22)", ("\u0e2a\u0e34\u0e48\u0e07\u0e17\u0e35\u0e48\u0e15\u0e25\u0e32\u0e14\u0e04\u0e32\u0e14\u0e02\u0e49\u0e32\u0e07\u0e2b\u0e19\u0e49\u0e32: %s \u00b7 " % fw["head"] if fw else "") + "\u0e15\u0e2d\u0e19\u0e19\u0e35\u0e49\u0e22\u0e31\u0e07\u0e44\u0e21\u0e48\u0e21\u0e35\u0e21\u0e38\u0e21\u0e17\u0e35\u0e48\u0e15\u0e49\u0e2d\u0e07\u0e08\u0e31\u0e1a\u0e15\u0e32\u0e40\u0e1b\u0e47\u0e19\u0e1e\u0e34\u0e40\u0e28\u0e29 \u0e20\u0e32\u0e1e\u0e19\u0e48\u0e32\u0e08\u0e30\u0e40\u0e1b\u0e25\u0e35\u0e48\u0e22\u0e19\u0e40\u0e21\u0e37\u0e48\u0e2d\u0e21\u0e35\u0e07\u0e1a\u0e2b\u0e23\u0e37\u0e2d\u0e02\u0e48\u0e32\u0e27\u0e43\u0e2b\u0e21\u0e48"))
    return rows


def sum_principles(pr):
    """\u0e2a\u0e48\u0e27\u0e19 4: 23 \u0e2b\u0e25\u0e31\u0e01\u0e01\u0e32\u0e23 + \u0e42\u0e0b\u0e19\u0e23\u0e32\u0e04\u0e32 (\u0e43\u0e0a\u0e49\u0e1c\u0e25 principles.compute \u0e17\u0e35\u0e48\u0e04\u0e33\u0e19\u0e27\u0e13\u0e41\u0e25\u0e49\u0e27)"""
    if not pr:
        return []
    ps, rt, t, conf = (tuple(pr) + (None,) * 4)[:4]
    if not rt:
        return []
    import principles as P
    band = P._band(rt["quality"])[0]
    now = "\u0e04\u0e30\u0e41\u0e19\u0e19\u0e04\u0e38\u0e13\u0e20\u0e32\u0e1e\u0e42\u0e14\u0e22\u0e40\u0e09\u0e25\u0e35\u0e48\u0e22 %.0f \u0e40\u0e15\u0e47\u0e21 100 (%s) \u0e08\u0e32\u0e01 %d \u0e02\u0e49\u0e2d\u0e17\u0e35\u0e48\u0e04\u0e33\u0e19\u0e27\u0e13\u0e44\u0e14\u0e49" % (rt["quality"], band, rt["n"])
    extra = []
    if _ok(rt.get("growth")):
        extra.append("\u0e01\u0e32\u0e23\u0e40\u0e15\u0e34\u0e1a\u0e42\u0e15 %.0f" % rt["growth"])
    if _ok(rt.get("safety")):
        extra.append("\u0e04\u0e27\u0e32\u0e21\u0e21\u0e31\u0e48\u0e19\u0e04\u0e07\u0e17\u0e32\u0e07\u0e01\u0e32\u0e23\u0e40\u0e07\u0e34\u0e19 %.0f" % rt["safety"])
    if extra:
        now += " \u00b7 " + " \u00b7 ".join(extra)
    rows = [("\u0e15\u0e2d\u0e19\u0e19\u0e35\u0e49\u0e40\u0e1b\u0e47\u0e19\u0e22\u0e31\u0e07\u0e44\u0e07", now)]
    calc = sorted([p for p in ps if p.get("score") is not None], key=lambda x: -x["score"])
    short = lambda p: p["title"].split(" (")[0]
    weak = [p for p in calc[::-1] if p["score"] < 60][:2]
    rows.append(("\u0e08\u0e38\u0e14\u0e40\u0e14\u0e48\u0e19 / \u0e08\u0e38\u0e14\u0e17\u0e35\u0e48\u0e04\u0e27\u0e23\u0e40\u0e0a\u0e47\u0e01", "\u0e40\u0e14\u0e48\u0e19: %s \u00b7 %s" % (" \u0e41\u0e25\u0e30 ".join(short(p) for p in calc[:2]),
                ("\u0e04\u0e27\u0e23\u0e40\u0e0a\u0e47\u0e01: " + " \u0e41\u0e25\u0e30 ".join(short(p) for p in weak)) if weak else "\u0e22\u0e31\u0e07\u0e44\u0e21\u0e48\u0e21\u0e35\u0e02\u0e49\u0e2d\u0e17\u0e35\u0e48\u0e04\u0e30\u0e41\u0e19\u0e19\u0e15\u0e48\u0e33\u0e01\u0e27\u0e48\u0e32 60")))
    if t:
        px = t["px"]
        z = ["\u0e23\u0e32\u0e04\u0e32 %s" % format(px, ",.2f")]
        if t.get("sup"):
            z.append("\u0e41\u0e19\u0e27\u0e23\u0e31\u0e1a\u0e43\u0e01\u0e25\u0e49\u0e2a\u0e38\u0e14 %s (\u0e15\u0e48\u0e33\u0e01\u0e27\u0e48\u0e32 %.1f%%)" % (format(t["sup"][0]["mid"], ",.2f"), (1 - t["sup"][0]["mid"] / px) * 100))
        if t.get("res"):
            z.append("\u0e41\u0e19\u0e27\u0e15\u0e49\u0e32\u0e19\u0e43\u0e01\u0e25\u0e49\u0e2a\u0e38\u0e14 %s (%s)" % (format(t["res"][0]["mid"], ",.2f"), _pct((t["res"][0]["mid"] / px - 1) * 100, 1, True)))
        z.append("\u0e16\u0e49\u0e32\u0e1b\u0e34\u0e14\u0e2b\u0e25\u0e38\u0e14 %s \u0e16\u0e37\u0e2d\u0e27\u0e48\u0e32\u0e20\u0e32\u0e1e\u0e40\u0e2a\u0e35\u0e22" % format(t["stop"], ",.2f"))
        r_ = t["rsi"]
        z.append("RSI %.0f (%s)" % (r_, "\u0e23\u0e49\u0e2d\u0e19\u0e41\u0e23\u0e07" if r_ >= 70 else ("\u0e02\u0e32\u0e22\u0e21\u0e32\u0e01\u0e40\u0e01\u0e34\u0e19" if r_ <= 30 else "\u0e42\u0e0b\u0e19\u0e01\u0e25\u0e32\u0e07")))
        rows.append(("\u0e42\u0e0b\u0e19\u0e23\u0e32\u0e04\u0e32\u0e15\u0e2d\u0e19\u0e19\u0e35\u0e49", " \u00b7 ".join(z)))
        if px >= t["ema200"]:
            tr = "\u0e40\u0e17\u0e23\u0e19\u0e14\u0e4c\u0e23\u0e30\u0e22\u0e30\u0e22\u0e32\u0e27\u0e22\u0e31\u0e07\u0e40\u0e1b\u0e47\u0e19\u0e02\u0e32\u0e02\u0e36\u0e49\u0e19 (\u0e23\u0e32\u0e04\u0e32\u0e2d\u0e22\u0e39\u0e48\u0e40\u0e2b\u0e19\u0e37\u0e2d\u0e40\u0e2a\u0e49\u0e19 EMA200 \u0e0b\u0e36\u0e48\u0e07\u0e40\u0e1b\u0e47\u0e19\u0e40\u0e2a\u0e49\u0e19\u0e40\u0e09\u0e25\u0e35\u0e48\u0e22\u0e23\u0e30\u0e22\u0e30\u0e22\u0e32\u0e27) \u0e16\u0e49\u0e32\u0e23\u0e32\u0e04\u0e32\u0e22\u0e48\u0e2d\u0e25\u0e07\u0e21\u0e32\u0e43\u0e01\u0e25\u0e49\u0e41\u0e19\u0e27\u0e23\u0e31\u0e1a\u0e41\u0e25\u0e49\u0e27\u0e44\u0e21\u0e48\u0e2b\u0e25\u0e38\u0e14 \u0e20\u0e32\u0e1e\u0e01\u0e47\u0e22\u0e31\u0e07\u0e14\u0e35 \u0e41\u0e15\u0e48\u0e16\u0e49\u0e32\u0e2b\u0e25\u0e38\u0e14\u0e08\u0e38\u0e14\u0e17\u0e35\u0e48\u0e20\u0e32\u0e1e\u0e40\u0e2a\u0e35\u0e22 \u0e15\u0e49\u0e2d\u0e07\u0e01\u0e25\u0e31\u0e1a\u0e21\u0e32\u0e1b\u0e23\u0e30\u0e40\u0e21\u0e34\u0e19\u0e43\u0e2b\u0e21\u0e48"
        else:
            tr = "\u0e23\u0e32\u0e04\u0e32\u0e2d\u0e22\u0e39\u0e48\u0e43\u0e15\u0e49\u0e40\u0e2a\u0e49\u0e19 EMA200 (\u0e40\u0e2a\u0e49\u0e19\u0e40\u0e09\u0e25\u0e35\u0e48\u0e22\u0e23\u0e30\u0e22\u0e30\u0e22\u0e32\u0e27) \u0e41\u0e1b\u0e25\u0e27\u0e48\u0e32\u0e15\u0e2d\u0e19\u0e19\u0e35\u0e49\u0e40\u0e1b\u0e47\u0e19\u0e02\u0e32\u0e25\u0e07\u0e23\u0e30\u0e22\u0e30\u0e22\u0e32\u0e27 \u0e16\u0e36\u0e07\u0e04\u0e30\u0e41\u0e19\u0e19\u0e04\u0e38\u0e13\u0e20\u0e32\u0e1e\u0e08\u0e30%s \u0e23\u0e32\u0e04\u0e32\u0e08\u0e30\u0e14\u0e39\u0e14\u0e35\u0e02\u0e36\u0e49\u0e19\u0e0a\u0e31\u0e14\u0e46 \u0e01\u0e47\u0e15\u0e48\u0e2d\u0e40\u0e21\u0e37\u0e48\u0e2d\u0e01\u0e25\u0e31\u0e1a\u0e21\u0e32\u0e22\u0e37\u0e19\u0e40\u0e2b\u0e19\u0e37\u0e2d\u0e40\u0e2a\u0e49\u0e19\u0e19\u0e35\u0e49\u0e44\u0e14\u0e49" % ("\u0e14\u0e35" if rt["quality"] >= 60 else "\u0e44\u0e21\u0e48\u0e2a\u0e39\u0e07")
        rows.append(("\u0e41\u0e19\u0e27\u0e42\u0e19\u0e49\u0e21\u0e08\u0e32\u0e01\u0e15\u0e31\u0e27\u0e40\u0e25\u0e02 (\u0e44\u0e21\u0e48\u0e43\u0e0a\u0e48\u0e17\u0e33\u0e19\u0e32\u0e22)", tr + "."))
    if conf:
        rows.append(("\u0e04\u0e27\u0e32\u0e21\u0e19\u0e48\u0e32\u0e40\u0e0a\u0e37\u0e48\u0e2d\u0e16\u0e37\u0e2d\u0e02\u0e2d\u0e07\u0e02\u0e49\u0e2d\u0e21\u0e39\u0e25", "%s \u2014 %s" % ({"good": "\u0e2a\u0e39\u0e07", "mid": "\u0e1b\u0e32\u0e19\u0e01\u0e25\u0e32\u0e07", "bad": "\u0e15\u0e48\u0e33"}[conf["level"]], " ".join(conf["why"][:2]))))
    return rows


